css:
.are-search {
  /* theme: override these four to re-skin */
  --are-search-bg: oklch(0.972 0.012 84);
  --are-search-ink: oklch(0.27 0.03 52);
  --are-search-accent: oklch(0.6 0.155 38);
  --are-search-land: oklch(0.95 0.02 92);

  --are-search-surface: color-mix(in oklch, var(--are-search-bg) 55%, white);
  --are-search-line: color-mix(in oklch, var(--are-search-ink) 11%, transparent);
  --are-search-line2: color-mix(in oklch, var(--are-search-ink) 21%, transparent);
  --are-search-mute: color-mix(in oklch, var(--are-search-ink) 62%, var(--are-search-bg));
  --are-search-faint: color-mix(in oklch, var(--are-search-ink) 40%, var(--are-search-bg));
  --are-search-wash: color-mix(in oklch, var(--are-search-ink) 4%, var(--are-search-bg));
  --are-search-tint: color-mix(in oklch, var(--are-search-accent) 12%, var(--are-search-bg));
  --are-search-on: oklch(0.99 0.005 84);
  --are-search-water: color-mix(in oklch, var(--are-search-land) 42%, oklch(0.76 0.065 222));
  --are-search-park: color-mix(in oklch, var(--are-search-land) 52%, oklch(0.78 0.1 142));
  --are-search-road: color-mix(in oklch, var(--are-search-land) 25%, white);
  --are-search-street: color-mix(in oklch, var(--are-search-land) 70%, white);
  --are-search-ease: cubic-bezier(.2, .8, .2, 1);
  --are-search-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-search-h, 680px);
  container-type: inline-size; container-name: are-search;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-search-bg); color: var(--are-search-ink); color-scheme: light;
  accent-color: var(--are-search-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-search-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-search-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .45; }
  & h2, & h3, & h4, & p, & dl, & dd, & figure { margin: 0; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg .f { fill: currentColor; stroke: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; text-align: center;
    border: 1px solid var(--are-search-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-search-mute);
    background: var(--are-search-surface);
  }
}

.are-search .are-search-app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: minmax(330px, 34cqi) minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "top top" "list map";
}

/* ── top bar ─────────────────────────────────────── */
.are-search .are-search-top {
  grid-area: top; display: flex; align-items: center; gap: 14px; padding: 12px 16px;
  border-bottom: 1px solid var(--are-search-line); background: var(--are-search-bg); position: relative; z-index: 6;
}
.are-search .are-search-brand {
  display: flex; align-items: center; gap: 8px; font-size: 15px; letter-spacing: -.02em; white-space: nowrap;
  & svg { width: 24px; height: 24px; color: var(--are-search-accent); stroke-width: 1.9; }
  & b { font-weight: 760; }
}
.are-search .are-search-q {
  position: relative; flex: 1 1 auto; max-width: 460px; min-width: 0; display: flex; align-items: center; gap: 8px;
  padding: 0 10px; height: 38px; border-radius: 10px; background: var(--are-search-surface);
  box-shadow: inset 0 0 0 1px var(--are-search-line2); transition: box-shadow .2s;
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--are-search-accent); }
  & > svg { color: var(--are-search-mute); }
  & input { flex: 1 1 auto; min-width: 0; border: 0; background: none; outline: none; height: 100%; font-size: 13.5px; }
  & input::placeholder { color: var(--are-search-faint); }
  & input:focus-visible { outline: none; }
}
.are-search .are-search-hood {
  display: inline-flex; align-items: center; gap: 4px; white-space: nowrap;
  & button {
    display: inline-flex; align-items: center; gap: 4px; border: 0; border-radius: 6px; padding: 3px 6px 3px 8px;
    background: var(--are-search-tint); color: color-mix(in oklch, var(--are-search-accent) 70%, var(--are-search-ink)); font-weight: 650; font-size: 12px;
  }
  & svg { width: 12px; height: 12px; }
}
.are-search .are-search-sugg {
  position: absolute; left: 0; right: 0; top: calc(100% + 6px); z-index: 20; margin: 0; padding: 6px; list-style: none;
  background: var(--are-search-surface); border-radius: 12px;
  box-shadow: 0 0 0 1px var(--are-search-line), 0 18px 40px -16px color-mix(in oklch, var(--are-search-ink) 45%, transparent);
  transition: opacity .18s, translate .3s var(--are-search-ease);
  @starting-style { opacity: 0; translate: 0 -6px; }
  & li { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; cursor: pointer; }
  & li[aria-selected="true"], & li:hover { background: var(--are-search-tint); }
  & li svg { color: var(--are-search-mute); }
  & li b { font-weight: 600; }
  & li small { margin-left: auto; color: var(--are-search-mute); font-variant-numeric: tabular-nums; }
  & li.is-empty { cursor: default; color: var(--are-search-mute); background: none; }
}
.are-search .are-search-acts { display: flex; gap: 8px; margin-left: auto; }
.are-search .are-search-btn {
  display: inline-flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; white-space: nowrap;
  border: 0; background: var(--are-search-surface); box-shadow: inset 0 0 0 1px var(--are-search-line2); font-weight: 600; font-size: 12.5px;
  transition: background .2s, box-shadow .2s, color .2s, scale .35s var(--are-search-spring);
  &:hover:where(:not(:disabled)) { background: var(--are-search-wash); }
  &:active:where(:not(:disabled)) { scale: .96; }
  &[aria-pressed="true"], &[aria-expanded="true"] { background: var(--are-search-ink); color: var(--are-search-on); box-shadow: none; }
  & i {
    font-style: normal; font: 700 10.5px/1 system-ui; min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; display: grid; place-items: center;
    background: var(--are-search-accent); color: var(--are-search-on); font-variant-numeric: tabular-nums;
  }
  & kbd { margin-left: 2px; }
  &[aria-pressed="true"] kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--are-search-on) 35%, transparent); }
}
.are-search .are-search-savedbtn[aria-pressed="false"] svg { color: var(--are-search-accent); }
.are-search .are-search-savedbtn[aria-pressed="true"] svg { fill: currentColor; }
.are-search .are-search-ghost { box-shadow: none; background: none; height: 30px; padding: 0 8px; color: var(--are-search-mute); }

/* ── results list ────────────────────────────────── */
.are-search .are-search-list {
  grid-area: list; position: relative; min-height: 0; display: flex; flex-direction: column;
  border-right: 1px solid var(--are-search-line); background: var(--are-search-bg); overflow: clip;
}
.are-search .are-search-lhead {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 14px 16px 6px;
  & h2 { font-size: clamp(16px, 1.6cqi, 19px); font-weight: 760; letter-spacing: -.02em; text-wrap: balance; font-variant-numeric: tabular-nums; }
  & p { color: var(--are-search-mute); font-size: 12px; font-variant-numeric: tabular-nums; margin-top: 2px; }
}
.are-search .are-search-sort { position: relative; }
.are-search .are-search-menu {
  position: absolute; right: 0; top: calc(100% + 4px); z-index: 12; min-width: 210px; padding: 6px;
  background: var(--are-search-surface); border-radius: 12px;
  box-shadow: 0 0 0 1px var(--are-search-line), 0 16px 36px -14px color-mix(in oklch, var(--are-search-ink) 45%, transparent);
  transform-origin: top right; transition: opacity .16s, scale .3s var(--are-search-spring);
  @starting-style { opacity: 0; scale: .94; }
  & button {
    width: 100%; display: flex; align-items: center; gap: 10px; border: 0; background: none; text-align: left;
    padding: 8px 10px; border-radius: 8px; font-size: 13px;
  }
  & button:hover, & button:focus-visible { background: var(--are-search-tint); outline: none; }
  & button svg { opacity: 0; color: var(--are-search-accent); }
  & button[aria-checked="true"] { font-weight: 650; }
  & button[aria-checked="true"] svg { opacity: 1; }
}
.are-search .are-search-chips {
  display: flex; flex-wrap: wrap; gap: 6px; padding: 0 16px 10px; min-height: 0;
  &:empty { display: none; }
  & button {
    display: inline-flex; align-items: center; gap: 5px; height: 26px; padding: 0 6px 0 10px; border-radius: 13px; border: 0;
    background: var(--are-search-tint); color: color-mix(in oklch, var(--are-search-accent) 72%, var(--are-search-ink)); font-size: 12px; font-weight: 600;
    transition: background .2s;
    &:hover { background: color-mix(in oklch, var(--are-search-accent) 20%, var(--are-search-bg)); }
  }
  & button svg { width: 12px; height: 12px; }
  & .are-search-clr { background: none; color: var(--are-search-mute); padding: 0 8px; text-decoration: underline; text-underline-offset: 3px; }
}
.are-search .are-search-scroll {
  flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin;
  scrollbar-color: var(--are-search-line2) transparent; padding: 2px 12px 16px;
  border-top: 1px solid transparent;
  animation: are-search-edge linear both; animation-timeline: scroll(self); animation-range: 0 40px;
}
@supports not (animation-timeline: scroll()) {
  .are-search .are-search-scroll { animation: none; border-top-color: var(--are-search-line); }
}
.are-search .are-search-cards { display: grid; gap: 8px; }
.are-search .are-search-card {
  position: relative; display: grid; grid-template-columns: clamp(104px, 11cqi, 132px) minmax(0, 1fr); gap: 12px; align-items: center;
  padding: 8px; border-radius: 14px; background: var(--are-search-surface);
  box-shadow: 0 0 0 1px var(--are-search-line);
  transition: box-shadow .25s, translate .35s var(--are-search-ease);
  &:hover, &.is-hot { box-shadow: 0 0 0 1px var(--are-search-line2), 0 10px 24px -14px color-mix(in oklch, var(--are-search-ink) 50%, transparent); translate: 0 -1px; }
  &.is-hot .are-search-pr b { color: var(--are-search-accent); }
  &:has(.are-search-cardbtn:focus-visible) { box-shadow: 0 0 0 2px var(--are-search-accent); }
  &.is-open { box-shadow: 0 0 0 2px var(--are-search-accent); }
}
.are-search .are-search-ph {
  position: relative; aspect-ratio: 4 / 3; border-radius: 9px; overflow: hidden; background: var(--are-search-wash);
  & > svg { width: 100%; height: 100%; display: block; stroke: none; }
}
.are-search .are-search-badge {
  position: absolute; left: 6px; top: 6px; padding: 2px 6px; border-radius: 5px; font: 700 9.5px/1.4 system-ui; letter-spacing: .04em; text-transform: uppercase;
  background: var(--are-search-surface); color: var(--are-search-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--are-search-ink) 25%, transparent);
  &.is-new { background: var(--are-search-accent); color: var(--are-search-on); }
  &.is-cut { background: oklch(0.42 0.06 160); color: var(--are-search-on); }
}
.are-search .are-search-ci { min-width: 0; display: grid; gap: 2px; padding-right: 30px; }
.are-search .are-search-pr {
  display: flex; align-items: baseline; gap: 8px; font-variant-numeric: tabular-nums;
  & b { font-size: clamp(16px, 1.55cqi, 18px); font-weight: 780; letter-spacing: -.02em; transition: color .2s; }
  & span { font-size: 11.5px; color: var(--are-search-mute); }
}
.are-search .are-search-sp {
  display: flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 550; font-variant-numeric: tabular-nums;
  & i { width: 3px; height: 3px; border-radius: 50%; background: var(--are-search-faint); }
}
.are-search .are-search-ad { font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.are-search .are-search-hd { font-size: 11.5px; color: var(--are-search-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.are-search .are-search-cardbtn { position: absolute; inset: 0; z-index: 1; border: 0; background: none; border-radius: 14px; }
.are-search .are-search-cardbtn:focus-visible { outline: none; }
.are-search .are-search-heart {
  position: absolute; z-index: 2; right: 8px; top: 8px; width: 30px; height: 30px; border-radius: 50%; border: 0; display: grid; place-items: center;
  background: none; color: var(--are-search-faint); transition: color .2s, background .2s, scale .4s var(--are-search-spring);
  &:hover { background: var(--are-search-wash); color: var(--are-search-accent); }
  &:active { scale: .85; }
  &[aria-pressed="true"] { color: var(--are-search-accent); }
  &[aria-pressed="true"] svg { fill: currentColor; animation: are-search-pop .45s var(--are-search-spring); }
}
.are-search .are-search-empty {
  display: grid; gap: 10px; justify-items: start; padding: 26px 8px;
  & h3 { font-size: 16px; font-weight: 720; letter-spacing: -.01em; text-wrap: balance; }
  & p { color: var(--are-search-mute); text-wrap: pretty; }
  & div { display: grid; gap: 6px; width: 100%; }
  & button {
    display: flex; justify-content: space-between; width: 100%; padding: 10px 12px; border-radius: 10px; border: 0;
    background: var(--are-search-surface); box-shadow: inset 0 0 0 1px var(--are-search-line2); font-weight: 600; text-align: left;
    &:hover { box-shadow: inset 0 0 0 1px var(--are-search-accent); }
    & span { color: var(--are-search-accent); font-variant-numeric: tabular-nums; }
  }
}

/* ── detail drawer (slides over the list) ────────── */
.are-search .are-search-detail {
  position: absolute; inset: 0; z-index: 5; display: flex; flex-direction: column; background: var(--are-search-bg);
  translate: -102% 0; visibility: hidden;
  transition: translate .5s var(--are-search-spring), visibility 0s linear .5s;
  &.is-open { translate: 0 0; visibility: visible; transition: translate .5s var(--are-search-spring), visibility 0s; }
}
.are-search .are-search-dhead {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--are-search-line);
  & > div { display: flex; gap: 4px; }
  & .are-search-btn { height: 30px; padding: 0 9px; }
}
.are-search .are-search-iconbtn {
  width: 30px; height: 30px; border-radius: 8px; border: 0; display: grid; place-items: center; background: none; color: var(--are-search-mute);
  &:hover:not(:disabled) { background: var(--are-search-wash); color: var(--are-search-ink); }
}
.are-search .are-search-dscroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 14px 16px 20px; display: flex; flex-direction: column; gap: 16px; & > * { flex: none; } }
.are-search .are-search-dart {
  position: relative; border-radius: 14px; overflow: hidden; aspect-ratio: 16 / 9;
  & > svg { width: 100%; height: 100%; display: block; stroke: none; }
  & .are-search-badge { left: 10px; top: 10px; font-size: 10.5px; }
}
.are-search .are-search-dtitle {
  display: grid; gap: 3px;
  & .are-search-pr b { font-size: clamp(22px, 2.4cqi, 28px); letter-spacing: -.03em; }
  & h3 { font-size: 15px; font-weight: 650; text-wrap: balance; }
  & p:not(.are-search-pr) { color: var(--are-search-mute); font-size: 12.5px; }
}
.are-search .are-search-facts {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1px; border-radius: 12px; overflow: hidden;
  background: var(--are-search-line); box-shadow: 0 0 0 1px var(--are-search-line);
  & div { background: var(--are-search-surface); padding: 9px 10px; display: grid; gap: 1px; }
  & dt { font-size: 10.5px; text-transform: uppercase; letter-spacing: .07em; color: var(--are-search-mute); font-weight: 600; }
  & dd { font-weight: 680; font-variant-numeric: tabular-nums; }
}
.are-search .are-search-blurb { text-wrap: pretty; color: color-mix(in oklch, var(--are-search-ink) 85%, var(--are-search-bg)); line-height: 1.55; }
.are-search .are-search-sec {
  display: grid; gap: 8px;
  & h4 { font-size: 11px; text-transform: uppercase; letter-spacing: .09em; color: var(--are-search-mute); font-weight: 680; }
}
.are-search .are-search-pay {
  display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--are-search-surface); box-shadow: inset 0 0 0 1px var(--are-search-line);
  & > b { font-size: 20px; font-weight: 760; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & > b small { font-size: 12px; font-weight: 500; color: var(--are-search-mute); letter-spacing: 0; }
  & .are-search-bar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; gap: 2px; }
  & .are-search-bar i { display: block; height: 100%; flex: var(--w) 0 0; background: var(--c); transform-origin: left; animation: are-search-grow .7s var(--are-search-ease) both; animation-delay: calc(var(--i) * 70ms); }
  & ul { margin: 0; padding: 0; list-style: none; display: grid; gap: 3px; font-size: 12px; font-variant-numeric: tabular-nums; }
  & li { display: flex; align-items: center; gap: 8px; }
  & li::before { content: ""; width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & li span { margin-left: auto; font-weight: 600; }
  & p { font-size: 11.5px; color: var(--are-search-mute); }
}
.are-search .are-search-hist {
  margin: 0; padding: 0; list-style: none; display: grid; font-size: 12.5px; font-variant-numeric: tabular-nums;
  & li { display: grid; grid-template-columns: 88px 1fr auto; gap: 8px; padding: 7px 0; border-bottom: 1px dashed var(--are-search-line2); }
  & li:last-child { border-bottom: 0; }
  & span { color: var(--are-search-mute); }
  & b { font-weight: 650; }
  & em { font-style: normal; color: oklch(0.45 0.08 160); font-weight: 650; }
}
.are-search .are-search-pick {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button {
    border: 0; border-radius: 9px; padding: 7px 10px; background: var(--are-search-surface); box-shadow: inset 0 0 0 1px var(--are-search-line2);
    font-size: 12.5px; font-weight: 600; font-variant-numeric: tabular-nums; display: grid; text-align: left; line-height: 1.25;
    transition: box-shadow .2s, background .2s;
    & small { font-weight: 500; color: var(--are-search-mute); font-size: 11px; }
    &:hover { box-shadow: inset 0 0 0 1px var(--are-search-accent); }
    &[aria-checked="true"] { background: var(--are-search-ink); color: var(--are-search-on); box-shadow: none; }
    &[aria-checked="true"] small { color: color-mix(in oklch, var(--are-search-on) 70%, transparent); }
  }
}
.are-search .are-search-ok {
  display: grid; grid-template-columns: auto 1fr; gap: 4px 10px; align-items: center; padding: 12px; border-radius: 12px;
  background: color-mix(in oklch, oklch(0.6 0.1 160) 12%, var(--are-search-bg)); box-shadow: inset 0 0 0 1px color-mix(in oklch, oklch(0.6 0.1 160) 35%, transparent);
  & svg { width: 22px; height: 22px; color: oklch(0.48 0.1 160); grid-row: span 2; }
  & svg path { stroke-dasharray: 30; stroke-dashoffset: 30; animation: are-search-tick .5s .1s var(--are-search-ease) forwards; }
  & b { font-weight: 680; }
  & p { font-size: 12px; color: var(--are-search-mute); }
  & button { grid-column: 2; justify-self: start; }
}
.are-search .are-search-link {
  border: 0; background: none; padding: 0; color: var(--are-search-accent); font-weight: 650; text-decoration: underline; text-underline-offset: 3px; font-size: 12px;
}
.are-search .are-search-dfoot {
  display: flex; gap: 8px; padding: 10px 12px; border-top: 1px solid var(--are-search-line); background: var(--are-search-bg);
  & .are-search-btn { flex: 1 1 0; justify-content: center; }
  & .are-search-primary { background: var(--are-search-accent); color: var(--are-search-on); box-shadow: none; }
  & .are-search-primary:hover { background: color-mix(in oklch, var(--are-search-accent) 88%, black); }
  & .are-search-btn[aria-pressed="true"] svg { fill: currentColor; }
}
.are-search .are-search-share {
  display: flex; align-items: center; gap: 8px; padding: 8px 10px; border-radius: 10px; background: var(--are-search-wash); font: 12px ui-monospace, Menlo, monospace;
  & span { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  & b { font: 700 11px system-ui; color: oklch(0.45 0.1 160); }
}

/* ── map ─────────────────────────────────────────── */
.are-search .are-search-map { grid-area: map; position: relative; min-height: 0; overflow: hidden; background: var(--are-search-land); }
.are-search .are-search-svg {
  position: absolute; inset: 0; width: 100%; height: 100%; cursor: grab; touch-action: none; stroke: none; user-select: none;
  &.is-panning { cursor: grabbing; }
}
.are-search[data-draw] .are-search-svg { cursor: crosshair; }
