   One state object S drives the screen. results() derives the matching
   homes; the list, pins, chips, filter counts and detail re-render from it.
   A drawn area is a simplified polygon in map units, tested per home with
   ray casting. The camera is centre + units-per-pixel, so pins and labels
   are scaled by exactly that number and stay the same size at any zoom. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const SPRING = 'linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1)';
const EASE = 'cubic-bezier(.2,.8,.2,1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
const MODK = MAC ? '⌘' : 'Ctrl ';
const UID = Math.random().toString(36).slice(2, 7);

/* ids must be unique if the component is mounted twice */
$$('[id]').forEach(el => {
  const old = el.id, nu = old + '-' + UID; el.id = nu;
  $$('[aria-controls="' + old + '"], [aria-owns="' + old + '"]').forEach(r => ['aria-controls', 'aria-owns'].forEach(a => { if (r.getAttribute(a) === old) r.setAttribute(a, nu); }));
});

