.are-listing {
  /* theme: override these four to re-skin */
  --are-listing-bg: oklch(0.983 0.006 95);
  --are-listing-ink: oklch(0.25 0.028 165);
  --are-listing-accent: oklch(0.47 0.085 162);
  --are-listing-sun: oklch(0.8 0.135 76);

  --are-listing-paper: color-mix(in oklch, var(--are-listing-bg) 40%, white);
  --are-listing-line: color-mix(in oklch, var(--are-listing-ink) 11%, transparent);
  --are-listing-line2: color-mix(in oklch, var(--are-listing-ink) 22%, transparent);
  --are-listing-mute: color-mix(in oklch, var(--are-listing-ink) 60%, var(--are-listing-bg));
  --are-listing-faint: color-mix(in oklch, var(--are-listing-ink) 36%, var(--are-listing-bg));
  --are-listing-wash: color-mix(in oklch, var(--are-listing-ink) 4%, var(--are-listing-bg));
  --are-listing-tint: color-mix(in oklch, var(--are-listing-accent) 13%, var(--are-listing-bg));
  --are-listing-on: oklch(0.99 0.004 95);
  --are-listing-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --are-listing-ease: cubic-bezier(.2, .8, .2, 1);
  --are-listing-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-listing-h, 680px);
  container-type: inline-size; container-name: are-listing;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-listing-bg); color: var(--are-listing-ink); color-scheme: light;
  accent-color: var(--are-listing-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-listing-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-listing-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h1, & h2, & h3, & h4, & p, & ul, & figure { margin: 0; }
  & ul { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg .f { fill: currentColor; stroke: none; }
  & kbd {
    font: 600 10px/1 ui-monospace, Menlo, monospace; padding: 2px 4px; min-width: 16px; text-align: center;
    border: 1px solid var(--are-listing-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-listing-mute); background: var(--are-listing-paper);
  }
}

.are-listing .are-listing-app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(360px, 45cqi);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "top top" "tabs tabs" "left right";
}

/* ── header ───────────────────────────────────────── */
.are-listing .are-listing-top { grid-area: top; display: flex; align-items: center; gap: 18px; padding: 12px 18px; border-bottom: 1px solid var(--are-listing-line); }
.are-listing .are-listing-brand {
  display: flex; align-items: center; gap: 8px; white-space: nowrap;
  & svg { width: 22px; height: 22px; color: var(--are-listing-accent); }
  & b { font: 600 16px/1 var(--are-listing-serif); letter-spacing: -.01em; }
}
.are-listing .are-listing-crumbs {
  display: flex; align-items: center; gap: 4px; color: var(--are-listing-mute); font-size: 12.5px; min-width: 0; white-space: nowrap; overflow: hidden;
  & svg { width: 12px; height: 12px; color: var(--are-listing-faint); }
  & b { color: var(--are-listing-ink); font-weight: 600; overflow: hidden; text-overflow: ellipsis; }
}
.are-listing .are-listing-acts { margin-left: auto; display: flex; gap: 8px; }
.are-listing .are-listing-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; border: 0; white-space: nowrap;
  background: var(--are-listing-paper); box-shadow: inset 0 0 0 1px var(--are-listing-line2); font-weight: 600; font-size: 12.5px;
  transition: background .2s, box-shadow .2s, scale .35s var(--are-listing-spring), color .2s;
  &:hover:where(:not(:disabled)) { background: var(--are-listing-wash); }
  &:active:where(:not(:disabled)) { scale: .96; }
  &[aria-pressed="true"] { color: var(--are-listing-accent); box-shadow: inset 0 0 0 1.5px var(--are-listing-accent); }
  &[aria-pressed="true"] svg { fill: currentColor; animation: are-listing-pop .45s var(--are-listing-spring); }
}
.are-listing .are-listing-primary {
  background: var(--are-listing-accent); color: var(--are-listing-on); box-shadow: none;
  &:hover:where(:not(:disabled)) { background: color-mix(in oklch, var(--are-listing-accent) 86%, black); }
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--are-listing-on) 40%, transparent); }
}
.are-listing .are-listing-tabs { grid-area: tabs; display: none; }

/* ── left: gallery + details ─────────────────────── */
.are-listing .are-listing-left {
  grid-area: left; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--are-listing-line2) transparent;
  padding: 16px 18px 28px; display: flex; flex-direction: column; gap: 22px;
  & > * { flex: none; }
}
.are-listing .are-listing-gallery { display: grid; gap: 10px; }
.are-listing .are-listing-stage {
  position: relative; aspect-ratio: 16 / 10; border-radius: 14px; overflow: hidden; background: var(--are-listing-wash);
  box-shadow: 0 0 0 1px var(--are-listing-line);
}
.are-listing .are-listing-shots { position: absolute; inset: 0; }
.are-listing .are-listing-shot { position: absolute; inset: 0; & > svg { width: 100%; height: 100%; display: block; stroke: none; } }
.are-listing .are-listing-nav {
  position: absolute; top: 50%; translate: 0 -50%; width: 38px; height: 38px; border-radius: 50%; border: 0; display: grid; place-items: center; z-index: 2;
  background: color-mix(in oklch, var(--are-listing-paper) 88%, transparent); box-shadow: 0 4px 14px -6px color-mix(in oklch, var(--are-listing-ink) 50%, transparent);
  opacity: 0; transition: opacity .25s, scale .3s var(--are-listing-spring);
  &.is-prev { left: 12px; } &.is-next { right: 12px; }
  &:hover { scale: 1.06; }
  &:focus-visible { opacity: 1; }
}
.are-listing .are-listing-stage:hover .are-listing-nav, .are-listing .are-listing-stage:focus-within .are-listing-nav { opacity: 1; }
.are-listing .are-listing-cap {
  position: absolute; left: 12px; bottom: 12px; z-index: 2; display: grid; padding: 7px 11px; border-radius: 10px; line-height: 1.25;
  background: color-mix(in oklch, var(--are-listing-ink) 72%, transparent); color: var(--are-listing-on); backdrop-filter: blur(6px);
  & b { font-weight: 650; }
  & span { font-size: 11.5px; opacity: .8; font-variant-numeric: tabular-nums; }
}
.are-listing .are-listing-count { position: absolute; right: 54px; bottom: 14px; z-index: 2; font: 600 11.5px/1 ui-monospace, Menlo, monospace; padding: 6px 8px; border-radius: 7px; background: color-mix(in oklch, var(--are-listing-ink) 72%, transparent); color: var(--are-listing-on); font-variant-numeric: tabular-nums; }
.are-listing .are-listing-expand {
  position: absolute; right: 12px; bottom: 10px; z-index: 2; width: 34px; height: 34px; border-radius: 9px; border: 0; display: grid; place-items: center;
  background: color-mix(in oklch, var(--are-listing-ink) 72%, transparent); color: var(--are-listing-on);
  &:hover { background: var(--are-listing-ink); }
}
.are-listing .are-listing-thumbs {
  display: flex; gap: 8px; overflow-x: auto; scrollbar-width: none; padding: 2px; scroll-snap-type: x proximity;
  & button {
    flex: none; width: 78px; aspect-ratio: 4 / 3; border-radius: 8px; overflow: hidden; border: 0; padding: 0; position: relative; scroll-snap-align: start;
    box-shadow: 0 0 0 1px var(--are-listing-line); opacity: .72; transition: opacity .25s, box-shadow .25s, translate .3s var(--are-listing-ease);
    & svg { width: 100%; height: 100%; display: block; stroke: none; }
    &:hover { opacity: 1; translate: 0 -2px; }
    &[aria-selected="true"] { opacity: 1; box-shadow: 0 0 0 2px var(--are-listing-accent); }
    &.is-lit::after { content: ""; position: absolute; right: 4px; top: 4px; width: 7px; height: 7px; border-radius: 50%; background: var(--are-listing-sun); box-shadow: 0 0 0 1.5px var(--are-listing-paper); }
  }
}
.are-listing .are-listing-info { display: grid; gap: 16px; }
.are-listing .are-listing-head { display: grid; gap: 4px; }
.are-listing .are-listing-kicker { font-size: 11px; font-weight: 650; text-transform: uppercase; letter-spacing: .12em; color: var(--are-listing-accent); }
.are-listing .are-listing-price { font: 500 clamp(28px, 3.2cqi, 38px)/1.05 var(--are-listing-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums lining-nums; }
.are-listing .are-listing-addr { font-size: 15px; font-weight: 550; text-wrap: balance; }
.are-listing .are-listing-stats {
  display: flex; flex-wrap: wrap; gap: 6px 14px; margin-top: 6px; font-variant-numeric: tabular-nums; color: var(--are-listing-mute);
  & b { color: var(--are-listing-ink); font-weight: 680; }
}
.are-listing .are-listing-copy { text-wrap: pretty; line-height: 1.6; max-width: 62ch; color: color-mix(in oklch, var(--are-listing-ink) 86%, var(--are-listing-bg)); }
.are-listing .are-listing-feats {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px;
  & li { display: flex; gap: 10px; padding: 12px; border-radius: 12px; background: var(--are-listing-paper); box-shadow: inset 0 0 0 1px var(--are-listing-line); }
  & li svg { width: 20px; height: 20px; color: var(--are-listing-accent); }
  & span { display: grid; gap: 1px; font-size: 12px; color: var(--are-listing-mute); text-wrap: pretty; }
  & b { font-size: 13px; color: var(--are-listing-ink); font-weight: 650; }
}
.are-listing .are-listing-agent {
  display: flex; align-items: center; gap: 12px; padding: 12px; border-radius: 14px; background: var(--are-listing-tint);
  & div { flex: 1 1 auto; display: grid; min-width: 0; }
  & span:not(.are-listing-av) { font-size: 12px; color: var(--are-listing-mute); }
}
.are-listing .are-listing-av { width: 40px; height: 40px; border-radius: 50%; display: grid; place-items: center; font-weight: 700; font-size: 13px; background: var(--are-listing-accent); color: var(--are-listing-on); flex: none; }

/* ── right: floor plan ────────────────────────────── */
.are-listing .are-listing-right {
  grid-area: right; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto minmax(120px, 34%);
  border-left: 1px solid var(--are-listing-line); background: var(--are-listing-paper);
}
.are-listing .are-listing-ptools { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 12px 14px 0; }
.are-listing .are-listing-seg {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--are-listing-wash); box-shadow: inset 0 0 0 1px var(--are-listing-line);
  & button { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border: 0; border-radius: 7px; background: none; font-weight: 600; font-size: 12.5px; color: var(--are-listing-mute); transition: background .2s, color .2s, box-shadow .2s; }
  & button[aria-selected="true"], & button[aria-checked="true"] { background: var(--are-listing-paper); color: var(--are-listing-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--are-listing-ink) 18%, transparent), 0 0 0 1px var(--are-listing-line); }
  &.is-small button { padding: 0 9px; font-family: ui-monospace, Menlo, monospace; }
}
.are-listing .are-listing-plan { position: relative; min-height: 0; padding: 4px 10px; }
.are-listing .are-listing-svg {
  width: 100%; height: 100%; display: block; stroke: none; overflow: visible;
  & .are-listing-floor { transition: opacity .35s var(--are-listing-ease), translate .45s var(--are-listing-spring); }
  & .are-listing-floor.is-off { opacity: 0; translate: 0 6px; pointer-events: none; }
  & .are-listing-room { fill: var(--are-listing-paper); stroke: var(--are-listing-ink); stroke-width: .7; cursor: pointer; outline: none; transition: fill .3s; }
  & .are-listing-room.is-sun { fill: color-mix(in oklch, var(--are-listing-sun) 20%, var(--are-listing-paper)); }
  & .are-listing-room:hover, & .are-listing-room.is-hot { fill: color-mix(in oklch, var(--are-listing-accent) 14%, var(--are-listing-paper)); }
  & .are-listing-room.is-sel { fill: color-mix(in oklch, var(--are-listing-accent) 16%, var(--are-listing-paper)); }
  & .are-listing-room:focus-visible { stroke: var(--are-listing-accent); stroke-width: 1.6; }
  & .are-listing-selbox { fill: none; stroke: var(--are-listing-accent); stroke-width: 1.1; rx: .8px; pointer-events: none; transition: x .5s var(--are-listing-spring), y .5s var(--are-listing-spring), width .5s var(--are-listing-spring), height .5s var(--are-listing-spring), opacity .25s; }
  & .are-listing-outer { fill: none; stroke: var(--are-listing-ink); stroke-width: 2.4; pointer-events: none; }
  & .are-listing-win { stroke: var(--are-listing-paper); stroke-width: 2.6; pointer-events: none; }
  & .are-listing-win2 { stroke: var(--are-listing-ink); stroke-width: .45; pointer-events: none; }
  & .are-listing-door { fill: none; stroke: var(--are-listing-faint); stroke-width: .45; stroke-dasharray: 1 1; pointer-events: none; }
  & .are-listing-gap { stroke: var(--are-listing-paper); stroke-width: 1.4; pointer-events: none; }
  & .are-listing-stair { stroke: var(--are-listing-faint); stroke-width: .4; pointer-events: none; }
  & .are-listing-patch { fill: var(--are-listing-sun); opacity: .5; pointer-events: none; mix-blend-mode: multiply; transition: opacity .3s; }
  & .are-listing-rl { font: 650 3.3px system-ui; fill: var(--are-listing-ink); text-anchor: middle; pointer-events: none; }
  & .are-listing-rd { font: 500 2.7px ui-monospace, Menlo, monospace; fill: var(--are-listing-mute); text-anchor: middle; pointer-events: none; font-variant-numeric: tabular-nums; }
  & .are-listing-dim { stroke: var(--are-listing-faint); stroke-width: .3; }
  & .are-listing-dimt { font: 500 2.6px ui-monospace, Menlo, monospace; fill: var(--are-listing-mute); text-anchor: middle; }
  & .are-listing-compass { pointer-events: none; }
  & .are-listing-compass text { font: 700 3px system-ui; fill: var(--are-listing-ink); text-anchor: middle; }
  & .are-listing-sunmark { transition: transform .6s var(--are-listing-ease); }
  & .are-listing-sundisc { fill: var(--are-listing-sun); stroke: var(--are-listing-paper); stroke-width: .8; }
  & .are-listing-ray { stroke: var(--are-listing-sun); stroke-width: .5; stroke-dasharray: 1.2 1.6; animation: are-listing-flow 1.4s linear infinite; }
}
.are-listing.is-off .are-listing-ray { animation-play-state: paused; }
.are-listing .are-listing-tip {
  position: absolute; z-index: 3; pointer-events: none; padding: 7px 10px; border-radius: 9px; background: var(--are-listing-ink); color: var(--are-listing-on);
  font-size: 12px; line-height: 1.3; white-space: nowrap; display: grid; translate: -50% calc(-100% - 10px);
  box-shadow: 0 10px 24px -10px color-mix(in oklch, var(--are-listing-ink) 70%, transparent);
  transition: opacity .15s, scale .25s var(--are-listing-spring);
