}
.are-listing .are-listing-play {
  width: 32px; height: 32px; border-radius: 50%; border: 0; display: grid; place-items: center; flex: none;
  background: var(--are-listing-sun); color: oklch(0.3 0.06 70); transition: scale .3s var(--are-listing-spring);
