.are-listing .are-listing-vh { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.are-listing .are-listing-clock { font: 650 15px/1 ui-monospace, Menlo, monospace; font-variant-numeric: tabular-nums; min-width: 46px; text-align: right; }
