/* ── Calder & Finch · listing with a linked floor plan ──────────────────
   Rooms are rectangles in decimetres that tile each floor exactly, so the
   areas in the table always sum to the floor total. Windows carry a compass
   side; a simple sun model for early October (azimuth and altitude by hour)
   decides which windows take direct light, which rooms glow on the plan,
   where the light patches fall, and how each room's illustration is lit. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
