const EASE = 'cubic-bezier(.2,.8,.2,1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const UID = Math.random().toString(36).slice(2, 7);

const I = {
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>',
  prev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>',
  next: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6"/></svg>',
  play: '<path d="M8 5.5v13l11-6.5z" class="f"/>',
  pause: '<path d="M8 5.5h3v13H8zM13 5.5h3v13h-3z" class="f"/>',
  sun: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2"/></svg>',
  done: '<svg viewBox="0 0 56 56" aria-hidden="true"><circle cx="28" cy="28" r="22"/><path d="m18 29 7 7 13-15"/></svg>',
  cal: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="4" y="5.5" width="16" height="14" rx="2"/><path d="M4 10h16M9 3.5v4M15 3.5v4"/></svg>',
};

/* ── the house ────────────────────────────────────────────────────────── */
const R = [
  { id: 'liv', f: 0, n: 'Living room', r: [0, 0, 50, 46], w: [['N', 10, 40], ['W', 12, 34]], t: 'living', c: 85 },
  { id: 'hall', f: 0, n: 'Hall', r: [50, 0, 68, 46], w: [], t: 'hall', c: 60 },
  { id: 'study', f: 0, n: 'Study', r: [68, 0, 112, 32], w: [['N', 78, 102], ['E', 8, 24]], t: 'study', c: 150 },
  { id: 'util', f: 0, n: 'Utility & WC', r: [68, 32, 112, 46], w: [['E', 35, 43]], t: 'util', c: 210 },
  { id: 'kit', f: 0, n: 'Kitchen', r: [56, 46, 112, 90], w: [['S', 64, 104], ['E', 54, 76]], t: 'kitchen', c: 170 },
  { id: 'din', f: 0, n: 'Dining room', r: [0, 46, 56, 90], w: [['S', 10, 46], ['W', 56, 80]], t: 'dining', c: 40 },
  { id: 'bed2', f: 1, n: 'Bedroom 2', r: [0, 0, 44, 38], w: [['N', 10, 34], ['W', 12, 28]], t: 'bed', c: 230 },
  { id: 'bath', f: 1, n: 'Bathroom', r: [44, 0, 70, 24], w: [['N', 50, 64]], t: 'bath', c: 195 },
  { id: 'bed3', f: 1, n: 'Bedroom 3', r: [70, 0, 112, 38], w: [['N', 80, 104], ['E', 10, 28]], t: 'bed', c: 120 },
  { id: 'land', f: 1, n: 'Landing', r: [44, 24, 70, 56], w: [], sky: true, t: 'landing', c: 70 },
  { id: 'ens', f: 1, n: 'En-suite', r: [0, 38, 44, 56], w: [['W', 41, 51]], t: 'bath', c: 165 },
  { id: 'laun', f: 1, n: 'Laundry', r: [70, 38, 112, 56], w: [['E', 42, 52]], t: 'util', c: 95 },
  { id: 'main', f: 1, n: 'Main bedroom', r: [0, 56, 62, 90], w: [['S', 12, 52], ['W', 62, 84]], t: 'bed', c: 30 },
  { id: 'bed4', f: 1, n: 'Bedroom 4', r: [62, 56, 112, 90], w: [['S', 72, 102], ['E', 62, 84]], t: 'bed', c: 140 },
];
const ROOM = Object.fromEntries(R.map(r => [r.id, r]));
const DOORS = [
  [0, 'v', 50, 30, 8, -1], [0, 'v', 68, 8, 8, 1], [0, 'v', 68, 36, 7, 1], [0, 'h', 58, 46, 8, 1], [0, 'h', 20, 46, 8, 1], [0, 'h', 54, 0, 10, 1],
  [1, 'h', 50, 24, 7, -1], [1, 'v', 44, 28, 7, -1], [1, 'v', 70, 28, 7, 1], [1, 'v', 70, 44, 7, 1], [1, 'h', 46, 56, 7, 1], [1, 'h', 62.5, 56, 7, 1], [1, 'h', 30, 56, 7, -1],
];
const OPEN = [[0, 'v', 56, 56, 24]];   /* kitchen–dining opening, no door */
R.forEach(r => { r.wd = r.r[2] - r.r[0]; r.ht = r.r[3] - r.r[1]; r.m2 = r.wd * r.ht / 100; });
const PHOTOS = [{ id: 'front', n: 'Front elevation', t: 'front' }, ...['liv', 'hall', 'study', 'kit', 'din', 'util', 'main', 'ens', 'bed2', 'bed3', 'bed4', 'bath', 'land', 'laun'].map(id => ({ id, room: id })), { id: 'garden', n: 'South garden', t: 'garden' }];

/* ── sun model: Port Alder, early October ─────────────────────────────── */
const RISE = 7.17, SET = 18.83, FACE = { N: 0, E: 90, S: 180, W: 270 };
const azAt = t => 97 + 166 * (t - RISE) / (SET - RISE);
const altAt = t => 32 * Math.sin(Math.PI * clamp((t - RISE) / (SET - RISE), 0, 1));
const winLit = (side, t) => t > RISE && t < SET && altAt(t) > 3 && Math.abs(((azAt(t) - FACE[side]) % 360 + 540) % 360 - 180) < 72;
const roomLit = (r, t) => r.sky ? t >= 10.5 && t <= 15.5 : r.w.some(w => winLit(w[0], t));
R.forEach(r => { let n = 0; for (let t = 7; t < 19; t += 0.25) if (roomLit(r, t + 0.125)) n += 0.25; r.sunH = n; });

/* ── state ────────────────────────────────────────────────────────────── */
const S = {
  floor: 0, units: 'm', time: 11.5, sel: 'liv', photo: 1, hot: null, playing: false, saved: false, shared: 0, tab: 'photos', sheet: false, light: false,
  bk: { day: null, slot: null, mode: 'person', errors: {}, done: false },
};
const DAYS = [['Sat', 3], ['Sun', 4], ['Mon', 5], ['Tue', 6], ['Wed', 7], ['Thu', 8]];
const SLOTS = ['10:00', '10:45', '11:30', '13:00', '14:15', '15:30', '16:45', '17:30'];
const taken = (d, s) => (d * 5 + s * 3) % 7 === 0 || (d === 1 && s < 2);

/* ── formatting ───────────────────────────────────────────────────────── */
const hhmm = t => String(Math.floor(t)).padStart(2, '0') + ':' + String(Math.round((t % 1) * 60)).padStart(2, '0');
function len(dm) {
  if (S.units === 'm') return (dm / 10).toFixed(1);
  let inch = Math.round(dm * 3.937), ft = Math.floor(inch / 12); inch -= ft * 12;
  return ft + '′' + inch + '″';
}
const dims = r => len(r.wd) + ' × ' + len(r.ht) + (S.units === 'm' ? ' m' : '');
const area = m2 => S.units === 'm' ? m2.toFixed(1) + ' m²' : Math.round(m2 * 10.7639).toLocaleString('en-US') + ' ft²';
const hrs = h => (h % 1 ? h.toFixed(1) : h) + ' h';
const floorTotal = f => R.filter(r => r.f === f).reduce((s, r) => s + r.m2, 0);

/* ── floor plan ───────────────────────────────────────────────────────── */
const plan = $('[data-plan]'), tip = $('[data-tip]'), planWrap = $('[data-planwrap]');
function buildPlan() {
  let defs = '<defs>';
  R.forEach(r => { defs += `<clipPath id="are-listing-k-${r.id}-${UID}"><rect x="${r.r[0]}" y="${r.r[1]}" width="${r.wd}" height="${r.ht}"/></clipPath>`; });
  defs += '</defs>';
  let g = defs;
  /* dimension lines */
  g += `<g aria-hidden="true"><path class="are-listing-dim" d="M0 -8H112M0 -10V-6M112 -10V-6M-8 0V90M-10 0H-6M-10 90H-6"/>
    <text class="are-listing-dimt" x="56" y="-9.4" data-dimw></text><text class="are-listing-dimt" transform="translate(-9.4 45) rotate(-90)" data-dimh2></text></g>`;
  [0, 1].forEach(f => {
    g += `<g class="are-listing-floor${f ? ' is-off' : ''}" data-floor="${f}">`;
    R.filter(r => r.f === f).forEach(r => {
      g += `<rect class="are-listing-room" data-act="room" data-id="${r.id}" role="button" tabindex="-1" x="${r.r[0]}" y="${r.r[1]}" width="${r.wd}" height="${r.ht}"/>`;
    });
    g += `<g data-patches="${f}"></g>`;
    /* stairs */
    if (f === 0) { for (let y = 8; y <= 40; y += 2.8) g += `<path class="are-listing-stair" d="M59 ${y}H67.4"/>`; g += '<path class="are-listing-stair" d="M59 6V41M63.2 38V10m-1.4 2 1.4-2 1.4 2"/>'; }
    else { for (let y = 30; y <= 52; y += 2.8) g += `<path class="are-listing-stair" d="M60 ${y}H69.4"/>`; g += '<path class="are-listing-stair" d="M60 28V54"/><rect x="47" y="29" width="10" height="16" rx="1" class="are-listing-door" style="stroke-dasharray:1.2 1"/>'; }
