function nearestRoom(id, dx, dy) {
  const a = ROOM[id], ax = a.r[0] + a.wd / 2, ay = a.r[1] + a.ht / 2;
  let best = null, bs = Infinity;
  R.filter(r => r.f === a.f && r !== a).forEach(r => {
    const vx = r.r[0] + r.wd / 2 - ax, vy = r.r[1] + r.ht / 2 - ay, along = vx * dx + vy * dy;
    if (along <= 0) return;
    const s = along + Math.abs(vx * dy - vy * dx) * 2;
