    case 'ArrowRight': if (!t.closest('[role="tablist"]') || t.closest('[data-thumbs]')) { e.preventDefault(); goPhoto(S.photo + 1); if (t.closest('[data-thumbs]')) $$('button', thumbs)[S.photo].focus(); } break;
    case 'ArrowLeft': if (!t.closest('[role="tablist"]') || t.closest('[data-thumbs]')) { e.preventDefault(); goPhoto(S.photo - 1); if (t.closest('[data-thumbs]')) $$('button', thumbs)[S.photo].focus(); } break;
    case '1': S.floor = 0; renderPlan(); renderTable(); renderTop(); break;
    case '2': S.floor = 1; renderPlan(); renderTable(); renderTop(); break;
    case 'u': case 'U': S.units = S.units === 'm' ? 'ft' : 'm'; renderPlan(); renderTable(); renderTop(); renderStage(0); break;
    case 'l': case 'L': play(!S.playing); break;
    case 'f': case 'F': S.light = !S.light; renderLight(); break;
    case 'b': case 'B': openSheet(true); break;
    case 's': case 'S': S.saved = !S.saved; renderTop(); toast(S.saved ? 'Saved to your shortlist' : 'Removed from your shortlist'); break;
  }
