/* ── Plumbline · mortgage planner ───────────────────────────────────────
   amortize() runs month by month in integer cents, so principal plus extra
   always sums to the loan exactly and every yearly row, the table total, the
   KPIs and the chart are the same numbers. The balance paths are always 121
   points long, which lets CSS transition the `d` property between scenarios. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const NS = 'http://www.w3.org/2000/svg';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
const UID = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => {
  const old = el.id, nu = old + '-' + UID; el.id = nu;
  $$(`[for="${old}"]`).forEach(l => l.setAttribute('for', nu));
  $$(`[aria-labelledby="${old}"]`).forEach(l => l.setAttribute('aria-labelledby', nu));
});
$('[data-modk]').textContent = MAC ? '⌘Z' : 'Ctrl Z';

const I = {
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>',
  chev: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>',
};
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const TERMS = [10, 15, 20, 25, 30];
const DEF = { price: 685000, down: 137000, term: 30, rate: 6.125, start: 2026 * 12 + 11, tax: 1.1, ins: 1380, hoa: 0, extra: 200, lump: 10000, lumpYr: 5 };
const S = {
  scens: [{ ...DEF }, { ...DEF, term: 15, rate: 5.5, extra: 0, lump: 0 }],
  cur: 0, ltab: 'table', pane: 'inputs', year: null, open: new Set(), copied: false,
};
const undoStack = [];
const snapshot = () => JSON.stringify({ scens: S.scens, cur: S.cur });
function pushUndo(s) { undoStack.push(s || snapshot()); if (undoStack.length > 60) undoStack.shift(); syncUndo(); }
function syncUndo() { const b = $('[data-act="undo"]'); b.disabled = !undoStack.length; b.title = undoStack.length ? 'Undo (' + (MAC ? '⌘Z' : 'Ctrl+Z') + ')' : 'Nothing to undo'; }
function undo() {
  const s = undoStack.pop();
  if (!s) return;
  const o = JSON.parse(s); S.scens = o.scens; S.cur = Math.min(o.cur, S.scens.length - 1);
  syncUndo(); fillForm(); render(); toast('Undone');
}

/* ── maths ────────────────────────────────────────────────────────────── */
function amortize(sc, ext = true) {
  const L = Math.round((sc.price - sc.down) * 100), r = sc.rate / 1200, n = sc.term * 12;
  const pmt = Math.round(r ? L * r / (1 - Math.pow(1 + r, -n)) : L / n);
  const pmiOn = sc.down / sc.price < 0.2, pmiM = pmiOn ? Math.round(L * 0.0055 / 12) : 0;
  const rows = []; let bal = L;
  for (let m = 1; m <= n && bal > 0; m++) {
    const int = Math.round(bal * r);
    let prin = m === n ? bal : Math.min(pmt - int, bal), ex = 0;
    if (ext) {
      ex = Math.min(Math.round(sc.extra * 100), bal - prin);
      if (sc.lump && m === (sc.lumpYr - 1) * 12 + 1) ex = Math.min(ex + Math.round(sc.lump * 100), bal - prin);
    }
    const pmi = pmiOn && bal > 0.78 * sc.price * 100 ? pmiM : 0;
    bal -= prin + ex;
    rows.push({ m, int, prin, ex, bal, pmi });
  }
  const sum = k => rows.reduce((s, x) => s + x[k], 0);
  return { L, pmt, pmiM: pmiOn ? pmiM : 0, rows, interest: sum('int'), extra: sum('ex'), months: rows.length, pmi: sum('pmi') };
}
function years(a) {
  const out = [];
  a.rows.forEach(x => {
    const k = Math.ceil(x.m / 12);
    const y = out[k - 1] || (out[k - 1] = { k, prin: 0, int: 0, ex: 0, n: 0, bal: 0, months: [] });
    y.prin += x.prin; y.int += x.int; y.ex += x.ex; y.n++; y.bal = x.bal; y.months.push(x);
  });
  return out;
}
function monthly(sc, a) {
  const parts = [
    ['Principal & interest', Math.round(a.pmt / 100), 'var(--are-mortgage-prin)'],
    ['Property tax', Math.round(sc.price * sc.tax / 1200), 'oklch(0.62 0.05 250)'],
    ['Insurance', Math.round(sc.ins / 12), 'oklch(0.72 0.06 160)'],
    ['PMI', Math.round(a.pmiM / 100), 'var(--are-mortgage-accent)'],
    ['HOA', Math.round(sc.hoa), 'oklch(0.6 0.03 60)'],
