  return { parts, total: parts.reduce((s, p) => s + p[1], 0) };
}
const usd = c => '$' + Math.round(c / 100).toLocaleString('en-US');
const usdc = c => (c < 0 ? '−$' : '$') + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const d0 = n => '$' + Math.round(n).toLocaleString('en-US');
const kfmt = c => { const d = c / 100; return !d ? '$0' : d >= 1e6 ? '$' + (d / 1e6).toFixed(2) + 'M' : '$' + Math.round(d / 1000) + 'k'; };
const monthName = (sc, m) => { const t = sc.start + m - 1; return MON[t % 12] + ' ' + Math.floor(t / 12); };
const calYear = (sc, k) => Math.floor((sc.start + k * 12 - 1) / 12);
const span = m => { const y = Math.floor(m / 12), r = m % 12; return (y ? y + ' yr' + (y > 1 ? 's' : '') : '') + (y && r ? ' ' : '') + (r ? r + ' mo' : '') || '0 mo'; };
const pct = (a, b) => (a / b * 100).toFixed(a / b * 100 % 1 ? 1 : 0) + '%';
const label = (sc, i) => `${'ABC'[i]} · ${sc.term}-yr ${+sc.rate.toFixed(3)}%`;

/* ── animated numbers ─────────────────────────────────────────────────── */
function animNum(el, to, fmt) {
  const from = el._v == null ? to : el._v;
  el._v = to;
  if (RM.matches || from === to) { el.textContent = fmt(to); return; }
  const t0 = performance.now(), dur = 520;
  cancelAnimationFrame(el._raf);
  const tick = now => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3);
    el.textContent = fmt(from + (to - from) * e);
    if (k < 1) el._raf = requestAnimationFrame(tick);
  };
  el._raf = requestAnimationFrame(tick);
}

/* ── form ─────────────────────────────────────────────────────────────── */
const form = $('[data-form]'), F = n => form.elements[n];
const sc = () => S.scens[S.cur];
const fmtInt = n => Math.round(n).toLocaleString('en-US');
const parseNum = v => { const n = parseFloat(String(v).replace(/[^0-9.]/g, '')); return isFinite(n) ? n : NaN; };
function fillForm(except) {
  const s = sc();
  const set = (n, v) => { if (F(n) && F(n) !== except && doc.activeElement !== F(n)) F(n).value = v; };
  set('price', fmtInt(s.price)); set('price-r', s.price);
  set('down', fmtInt(s.down)); set('downpct', +(s.down / s.price * 100).toFixed(1)); set('down-r', +(s.down / s.price * 100).toFixed(1));
  set('rate', s.rate.toFixed(3)); set('rate-r', s.rate);
  set('extra', fmtInt(s.extra)); set('extra-r', s.extra);
  set('lump', fmtInt(s.lump));
  set('tax', s.tax.toFixed(2)); set('ins', fmtInt(s.ins)); set('hoa', fmtInt(s.hoa));
  $('[data-terms]').innerHTML = TERMS.map(t => `<button type="button" role="radio" data-act="term" data-v="${t}" aria-checked="${s.term === t}" tabindex="${s.term === t ? 0 : -1}">${t}y</button>`).join('');
  $('[data-start]').textContent = MON[s.start % 12] + ' ' + Math.floor(s.start / 12);
  $('[data-lumpyr]').textContent = 'Year ' + s.lumpYr;
  const ly = $$('[data-act="lumpyr"]');
  ly[0].disabled = s.lumpYr <= 1; ly[0].title = ly[0].disabled ? 'Already in the first year' : 'One year earlier';
  ly[1].disabled = s.lumpYr >= s.term; ly[1].title = ly[1].disabled ? 'That is the last year of the loan' : 'One year later';
  $$('.are-mortgage-msg').forEach(m => { m.textContent = ''; });
  $$('[aria-invalid]', form).forEach(i => i.removeAttribute('aria-invalid'));
}
function fieldError(name, msg) {
  const f = F(name), box = f.closest('.are-mortgage-field'), m = $('.are-mortgage-msg', box);
  if (msg) f.setAttribute('aria-invalid', 'true'); else f.removeAttribute('aria-invalid');
  if (m) m.textContent = msg || '';
}
function applyInput(name, raw, commit) {
  const s = sc(), v = parseNum(raw);
  switch (name) {
    case 'price': case 'price-r':
      if (!(v >= 50000 && v <= 10000000)) { fieldError('price', 'Enter a price between $50,000 and $10,000,000'); return false; }
      { const p = s.down / s.price; s.price = Math.round(v); s.down = Math.round(s.price * p); } fieldError('price'); break;
    case 'down':
      if (!(v >= s.price * 0.03 && v < s.price)) { fieldError('down', `Between ${d0(s.price * 0.03)} (3%) and the home price`); return false; }
      s.down = Math.round(v); fieldError('down'); break;
    case 'downpct': case 'down-r':
      if (!(v >= 3 && v < 100)) { fieldError('down', 'Between 3% and 99%'); return false; }
      s.down = Math.round(s.price * v / 100); fieldError('down'); break;
    case 'rate': case 'rate-r':
      if (!(v >= 0.5 && v <= 15)) { fieldError('rate', 'Enter a rate between 0.5% and 15%'); return false; }
      s.rate = Math.round(v * 1000) / 1000; fieldError('rate'); break;
    case 'extra': case 'extra-r': s.extra = clamp(Math.round(v || 0), 0, 20000); break;
    case 'lump': s.lump = clamp(Math.round(v || 0), 0, 1000000); break;
    case 'tax': s.tax = clamp(isNaN(v) ? s.tax : v, 0, 5); break;
    case 'ins': s.ins = clamp(Math.round(v || 0), 0, 50000); break;
    case 'hoa': s.hoa = clamp(Math.round(v || 0), 0, 5000); break;
    default: return false;
  }
  if (commit) fillForm(); else fillForm(F(name));
  render();
  return true;
}
let preEdit = null;
form.addEventListener('focusin', e => { if (e.target.matches('input')) preEdit = snapshot(); });
form.addEventListener('pointerdown', e => { if (e.target.matches('input[type="range"]')) preEdit = snapshot(); });
form.addEventListener('input', e => { if (e.target.name) applyInput(e.target.name, e.target.value, false); });
form.addEventListener('change', e => {
  if (!e.target.name) return;
  applyInput(e.target.name, e.target.value, true);
  const now = snapshot();
  if (preEdit && preEdit !== now) pushUndo(preEdit);
  preEdit = now;
});
form.addEventListener('keydown', e => {
  const t = e.target;
  if (t.matches('input:not([type="range"])') && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) {
    e.preventDefault();
    const stepMap = { price: 5000, down: 1000, downpct: 0.5, rate: 0.125, extra: 25, lump: 1000, tax: 0.05, ins: 50, hoa: 10 };
    const st = (stepMap[t.name] || 1) * (e.shiftKey ? 10 : 1) * (e.key === 'ArrowUp' ? 1 : -1);
    const pre = snapshot();
    if (applyInput(t.name, String(parseNum(t.value) + st), false)) { t.value = t.name === 'rate' ? sc().rate.toFixed(3) : t.name === 'tax' ? sc().tax.toFixed(2) : t.name === 'downpct' ? +(sc().down / sc().price * 100).toFixed(1) : fmtInt(parseNum(t.value) + st); pushUndo(pre); preEdit = snapshot(); }
  }
  if (e.key === 'Enter' && t.matches('input')) { e.preventDefault(); t.blur(); }
});
form.addEventListener('submit', e => e.preventDefault());

/* ── header: scenarios ────────────────────────────────────────────────── */
function renderScens() {
  const box = $('[data-scens]'), n = S.scens.length;
  box.innerHTML = S.scens.map((s, i) => `<span class="are-mortgage-scen"><button type="button" role="tab" data-act="scen" data-v="${i}" aria-selected="${i === S.cur}" tabindex="${i === S.cur ? 0 : -1}" title="Scenario ${'ABC'[i]} (${i + 1})"><i>${'ABC'[i]}</i>${s.term}-yr ${+s.rate.toFixed(3)}%</button><button type="button" class="are-mortgage-del" data-act="delscen" data-v="${i}" aria-label="Delete scenario ${'ABC'[i]}" ${n < 2 ? 'disabled title="Keep at least one scenario"' : 'title="Delete scenario"'}>${I.x}</button></span>`).join('') +
    `<button type="button" class="are-mortgage-add" data-act="addscen" ${n >= 3 ? 'disabled title="Up to three scenarios"' : 'title="Duplicate the current scenario (N)"'}>${I.plus}Scenario</button>`;
