  $('[data-stack]').innerHTML = m.parts.map(p => `<i style="--w:${p[1]};--c:${p[2]}"></i>`).join('') + (s.extra ? `<i style="--w:${s.extra};--c:var(--are-mortgage-extra)"></i>` : '');
  $('[data-legend]').innerHTML = m.parts.map(p => `<li style="--c:${p[2]}">${p[0]} <b>${d0(p[1])}</b></li>`).join('') + (s.extra ? `<li style="--c:var(--are-mortgage-extra)">Extra <b>+${d0(s.extra)}</b></li>` : '');
