    <div><dt>Total interest</dt><dd data-n="int"></dd></div>
    <div><dt>Paid off</dt><dd>${payoff} <small>${span(a.months)}</small></dd></div>
    <div class="${saved > 0 ? 'is-good' : ''}"><dt>Extras save</dt><dd>${saved > 0 ? `<span data-n="saved"></span> <small>${span(sooner)} sooner</small>` : '<small>Add an extra payment</small>'}</dd></div>`;
  const intEl = $('[data-n="int"]', root); intEl._v = renderKpis._int; animNum(intEl, a.interest, v => usd(v)); renderKpis._int = a.interest;
  const sv = $('[data-n="saved"]', root); if (sv) { sv._v = renderKpis._sv; animNum(sv, saved, v => usd(v)); renderKpis._sv = saved; }
  const share = a.interest / (a.interest + a.L) * 100;
  $('[data-ring]').style.setProperty('--are-mortgage-share', share.toFixed(1) + '%');
  $('[data-share]').textContent = Math.round(share) + '%';
  $('[data-ring]').setAttribute('aria-label', `${Math.round(share)}% of everything paid to the lender is interest`);
}

/* ── chart ────────────────────────────────────────────────────────────── */
const chart = $('[data-chart]'), tipEl = $('[data-tip]'), chartBox = $('[data-chartbox]');
let CW = 600, CH = 200, built = false;
const PAD = { l: 54, r: 12, t: 8, b: 20 };
function geom(s) {
  const iw = CW - PAD.l - PAD.r, ih = CH - PAD.t - PAD.b, h1 = ih * 0.62, gap = 14, h2 = ih - h1 - gap;
  return { iw, h1, h2, top2: PAD.t + h1 + gap, x: yr => PAD.l + iw * yr / s.term };
}
function buildChart() {
