  for (let k = 0; k < 30; k++) g += `<rect class="are-mortgage-barP" data-k="${k}"/><rect class="are-mortgage-barX" data-k="${k}"/><rect class="are-mortgage-barI" data-k="${k}"/>`;
  g += `</g><path class="are-mortgage-area" data-p="area"/><path class="are-mortgage-lineB" data-p="b"/><path class="are-mortgage-lineA" data-p="a"/>
    <circle class="are-mortgage-lump" r="5" data-lump/><g data-cursor style="opacity:0"><path class="are-mortgage-cur" data-curl/><circle class="are-mortgage-dotB" r="3.5" data-dotb/><circle class="are-mortgage-dot" r="4" data-dota/></g>`;
