css:
.are-tours {
  /* theme: override these four to re-skin */
  --are-tours-bg: oklch(0.2 0.008 70);
  --are-tours-ink: oklch(0.95 0.008 90);
  --are-tours-accent: oklch(0.88 0.17 125);
  --are-tours-land: oklch(0.235 0.008 70);

  --are-tours-panel: color-mix(in oklch, var(--are-tours-bg) 88%, white);
  --are-tours-raise: color-mix(in oklch, var(--are-tours-bg) 80%, white);
  --are-tours-line: color-mix(in oklch, var(--are-tours-ink) 10%, transparent);
  --are-tours-line2: color-mix(in oklch, var(--are-tours-ink) 18%, transparent);
  --are-tours-mute: color-mix(in oklch, var(--are-tours-ink) 58%, var(--are-tours-bg));
  --are-tours-faint: color-mix(in oklch, var(--are-tours-ink) 34%, var(--are-tours-bg));
  --are-tours-on: oklch(0.2 0.03 125);
  --are-tours-wait: oklch(0.8 0.13 78);
  --are-tours-bad: oklch(0.68 0.19 25);
  --are-tours-water: color-mix(in oklch, var(--are-tours-land) 35%, oklch(0.33 0.06 245));
  --are-tours-park: color-mix(in oklch, var(--are-tours-land) 72%, oklch(0.42 0.07 150));
  --are-tours-road: color-mix(in oklch, var(--are-tours-land) 70%, var(--are-tours-ink) 12%);
  --are-tours-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --are-tours-ease: cubic-bezier(.2, .8, .2, 1);
  --are-tours-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-tours-h, 680px);
  container-type: inline-size; container-name: are-tours;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-tours-bg); color: var(--are-tours-ink); color-scheme: dark;
  accent-color: var(--are-tours-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-tours-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-tours-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & h4, & p, & ol, & ul, & dl, & dd { margin: 0; }
  & ol, & ul { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & svg .f { fill: currentColor; stroke: none; }
  & kbd { font: 600 10px/1 var(--are-tours-mono); padding: 2px 4px; min-width: 16px; text-align: center; border: 1px solid var(--are-tours-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-tours-mute); background: var(--are-tours-panel); }
}

.are-tours .are-tours-app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: minmax(330px, 33cqi) minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr) auto;
  grid-template-areas: "top top" "panes panes" "list map" "time time";
}

/* ── header ───────────────────────────────────────── */
.are-tours .are-tours-top { grid-area: top; display: flex; align-items: center; gap: 16px; padding: 10px 14px; border-bottom: 1px solid var(--are-tours-line); }
.are-tours .are-tours-brand {
  display: flex; align-items: baseline; gap: 8px; white-space: nowrap;
  & svg { width: 20px; height: 20px; align-self: center; color: var(--are-tours-accent); }
  & b { font-weight: 750; letter-spacing: -.01em; }
  & span { color: var(--are-tours-mute); font-size: 12px; }
}
.are-tours .are-tours-who {
  display: flex; align-items: center; gap: 9px; padding-left: 16px; border-left: 1px solid var(--are-tours-line); min-width: 0;
  & div { display: grid; line-height: 1.25; min-width: 0; }
  & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span:not(.are-tours-av) { font-size: 11.5px; color: var(--are-tours-mute); white-space: nowrap; }
}
.are-tours .are-tours-av { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; font: 750 11px/1 system-ui; background: oklch(0.55 0.09 50); color: var(--are-tours-ink); flex: none; }
.are-tours .are-tours-start {
  display: flex; align-items: center; gap: 2px; padding: 3px 3px 3px 10px; border-radius: 9px; background: var(--are-tours-panel); box-shadow: inset 0 0 0 1px var(--are-tours-line);
  & > span { font-size: 11.5px; color: var(--are-tours-mute); margin-right: 6px; white-space: nowrap; }
  & button { width: 26px; height: 26px; border-radius: 6px; border: 0; background: none; display: grid; place-items: center; color: var(--are-tours-mute); }
  & button:hover:where(:not(:disabled)) { background: var(--are-tours-raise); color: var(--are-tours-ink); }
  & output { font: 650 13px/1 var(--are-tours-mono); min-width: 44px; text-align: center; font-variant-numeric: tabular-nums; }
}
.are-tours .are-tours-acts { margin-left: auto; display: flex; gap: 6px; }
.are-tours .are-tours-btn {
  position: relative; overflow: hidden; display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 8px; border: 0; white-space: nowrap;
  background: var(--are-tours-panel); box-shadow: inset 0 0 0 1px var(--are-tours-line2); font-weight: 600; font-size: 12.5px;
  transition: background .2s, scale .3s var(--are-tours-spring);
  &:hover:where(:not(:disabled)) { background: var(--are-tours-raise); }
  &:active:where(:not(:disabled)) { scale: .96; }
  & .are-tours-bar { position: absolute; left: 0; bottom: 0; height: 2px; width: 100%; background: var(--are-tours-accent); transform-origin: left; scale: var(--p, 0) 1; }
}
.are-tours .are-tours-primary { background: var(--are-tours-accent); color: var(--are-tours-on); box-shadow: none; &:hover:where(:not(:disabled)) { background: color-mix(in oklch, var(--are-tours-accent) 88%, white); } }
.are-tours .are-tours-panes { grid-area: panes; display: none; }

/* ── stops list ───────────────────────────────────── */
.are-tours .are-tours-list { grid-area: list; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--are-tours-line); }
.are-tours .are-tours-sum {
  flex: none; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px; background: var(--are-tours-line); border-bottom: 1px solid var(--are-tours-line);
  & div { background: var(--are-tours-bg); padding: 10px 12px 9px; display: grid; gap: 2px; }
  & dt { font: 650 9.5px/1 var(--are-tours-mono); text-transform: uppercase; letter-spacing: .12em; color: var(--are-tours-mute); }
  & dd { font: 700 16px/1.1 var(--are-tours-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; }
  & dd.is-bad { color: var(--are-tours-bad); }
  & dd.is-good { color: var(--are-tours-accent); }
}
.are-tours .are-tours-scroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--are-tours-line2) transparent; padding: 10px 10px 16px; }
.are-tours .are-tours-stops { display: grid; gap: 0; position: relative; }
.are-tours .are-tours-leg {
  display: flex; align-items: center; gap: 8px; padding: 4px 0 4px 18px; font: 500 11px/1 var(--are-tours-mono); color: var(--are-tours-mute); font-variant-numeric: tabular-nums; min-height: 28px; white-space: nowrap;
  & i { width: 2px; align-self: stretch; background: repeating-linear-gradient(to bottom, var(--are-tours-faint) 0 3px, transparent 3px 6px); margin-right: 10px; }
  & svg { width: 13px; height: 13px; }
  & .is-wait { color: var(--are-tours-wait); }
}
.are-tours .are-tours-stop {
  position: relative; border-radius: 12px; background: var(--are-tours-panel); box-shadow: inset 0 0 0 1px var(--are-tours-line);
  transition: box-shadow .2s, background .2s;
  &.is-hot, &:hover { box-shadow: inset 0 0 0 1px var(--are-tours-line2); }
  &.is-sel { box-shadow: inset 0 0 0 1.5px var(--are-tours-accent); }
  &.is-bad { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--are-tours-bad) 55%, transparent); }
  &.is-drag { z-index: 5; background: var(--are-tours-raise); box-shadow: 0 18px 40px -14px black, inset 0 0 0 1.5px var(--are-tours-accent); scale: 1.02; cursor: grabbing; }
  &:has(.are-tours-main:focus-visible) { box-shadow: inset 0 0 0 2px var(--are-tours-accent); }
}
.are-tours .are-tours-row { display: grid; grid-template-columns: 22px 30px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 10px 10px 10px 4px; }
.are-tours .are-tours-grip {
  width: 22px; height: 36px; border: 0; background: none; display: grid; place-items: center; color: var(--are-tours-faint); cursor: grab; touch-action: none; border-radius: 6px;
  &:hover { color: var(--are-tours-ink); background: var(--are-tours-raise); }
}
.are-tours .are-tours-num {
  width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; font: 750 12.5px/1 var(--are-tours-mono);
  background: var(--are-tours-accent); color: var(--are-tours-on);
  &.is-wait { background: var(--are-tours-wait); }
  &.is-bad { background: var(--are-tours-bad); color: var(--are-tours-ink); }
}
.are-tours .are-tours-main {
  border: 0; background: none; padding: 0; text-align: left; min-width: 0; display: grid; gap: 1px; outline: none;
  & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11.5px; color: var(--are-tours-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .are-tours-when { font: 600 12px/1.3 var(--are-tours-mono); color: var(--are-tours-ink); }
  & .are-tours-when em { font-style: normal; color: var(--are-tours-bad); }
}
.are-tours .are-tours-side { display: flex; align-items: center; gap: 4px; }
.are-tours .are-tours-dur {
  height: 26px; padding: 0 8px; border-radius: 7px; border: 0; background: var(--are-tours-raise); font: 650 11.5px/1 var(--are-tours-mono); font-variant-numeric: tabular-nums;
  &:hover { background: color-mix(in oklch, var(--are-tours-raise) 80%, white); }
}
.are-tours .are-tours-x { width: 26px; height: 26px; border-radius: 7px; border: 0; background: none; display: grid; place-items: center; color: var(--are-tours-faint); &:hover:where(:not(:disabled)) { background: var(--are-tours-raise); color: var(--are-tours-bad); } }
.are-tours .are-tours-more {
  display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--are-tours-ease);
  & > div { overflow: hidden; }
  &.is-open { grid-template-rows: 1fr; }
}
.are-tours .are-tours-detail {
  display: grid; gap: 8px; padding: 0 12px 12px 64px; font-size: 12px;
  & dl { display: grid; grid-template-columns: auto 1fr; gap: 3px 12px; }
  & dt { color: var(--are-tours-mute); }
  & dd { font-variant-numeric: tabular-nums; }
  & p { color: var(--are-tours-mute); text-wrap: pretty; }
  & .are-tours-warn { color: var(--are-tours-bad); font-weight: 600; }
  & .are-tours-row2 { display: flex; gap: 6px; flex-wrap: wrap; }
}
.are-tours .are-tours-st {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 10px; border-radius: 7px; border: 0; font-weight: 600; font-size: 11.5px;
  background: color-mix(in oklch, var(--are-tours-wait) 18%, transparent); color: var(--are-tours-wait);
  &::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: currentColor; }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--are-tours-accent) 16%, transparent); color: var(--are-tours-accent); }
}
.are-tours .are-tours-ghost { height: 26px; padding: 0 10px; border-radius: 7px; border: 0; background: var(--are-tours-raise); font-weight: 600; font-size: 11.5px; &:hover { background: color-mix(in oklch, var(--are-tours-raise) 80%, white); } }
.are-tours .are-tours-end { display: flex; align-items: center; gap: 10px; padding: 8px 0 0 18px; font: 600 11.5px/1.3 var(--are-tours-mono); color: var(--are-tours-mute); font-variant-numeric: tabular-nums; & svg { color: var(--are-tours-accent); } }
.are-tours .are-tours-tray {
  margin-top: 16px; padding-top: 12px; border-top: 1px dashed var(--are-tours-line2); display: grid; gap: 6px;
  & h4 { font: 650 10px/1 var(--are-tours-mono); text-transform: uppercase; letter-spacing: .12em; color: var(--are-tours-mute); margin-bottom: 2px; }
  & p { color: var(--are-tours-faint); font-size: 12px; }
}
.are-tours .are-tours-cand {
  display: flex; align-items: center; gap: 10px; padding: 8px 8px 8px 12px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--are-tours-line);
  & div { flex: 1 1 auto; display: grid; min-width: 0; }
  & b { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span { font-size: 11.5px; color: var(--are-tours-mute); font-variant-numeric: tabular-nums; }
  transition: opacity .3s, translate .4s var(--are-tours-spring);
  @starting-style { opacity: 0; translate: 0 6px; }
}
.are-tours .are-tours-keys { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 4px; padding: 8px 12px; border-top: 1px solid var(--are-tours-line); font-size: 11px; color: var(--are-tours-mute); & kbd + kbd { margin-left: -1px; } & kbd:not(:first-child) { margin-left: 2px; } }

/* ── map ──────────────────────────────────────────── */
.are-tours .are-tours-map { grid-area: map; position: relative; min-height: 0; background: var(--are-tours-land); overflow: hidden; }
.are-tours .are-tours-svg {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; stroke: none;
  & .are-tours-streets { stroke: var(--are-tours-road); stroke-width: 2.4; fill: none; opacity: .55; }
  & .are-tours-water { fill: var(--are-tours-water); }
  & .are-tours-river { fill: none; stroke: var(--are-tours-water); stroke-linecap: round; }
  & .are-tours-park { fill: var(--are-tours-park); }
  & .are-tours-artery { fill: none; stroke: color-mix(in oklch, var(--are-tours-road) 80%, var(--are-tours-ink) 12%); stroke-width: 7; stroke-linecap: round; }
  & .are-tours-lbl { font: 700 13px system-ui; letter-spacing: .3em; fill: var(--are-tours-faint); text-anchor: middle; text-transform: uppercase; opacity: .7; }
  & .are-tours-routeglow { fill: none; stroke: var(--are-tours-accent); stroke-width: 12px; stroke-opacity: .13; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
  & .are-tours-route { fill: none; stroke: var(--are-tours-accent); stroke-width: 3px; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
  & .are-tours-ants { fill: none; stroke: var(--are-tours-on); stroke-width: 1.4px; stroke-dasharray: 2 12; stroke-linecap: round; animation: are-tours-ants 1.2s linear infinite; opacity: .85; vector-effect: non-scaling-stroke; }
  & .are-tours-mk { cursor: pointer; outline: none; }
  & .are-tours-hit { fill: transparent; stroke: none; }
  & .are-tours-mk:hover .are-tours-hit, & .are-tours-mk:focus-visible .are-tours-hit { fill: color-mix(in oklch, var(--are-tours-ink) 7%, transparent); }
  & .are-tours-mk circle.is-o { fill: var(--are-tours-accent); stroke: var(--are-tours-bg); stroke-width: 2.5; }
  & .are-tours-mk.is-wait circle.is-o { fill: var(--are-tours-wait); }
  & .are-tours-mk.is-bad circle.is-o { fill: var(--are-tours-bad); }
  & .are-tours-mk text { font: 800 12px var(--are-tours-mono); fill: var(--are-tours-on); text-anchor: middle; pointer-events: none; }
  & .are-tours-mk.is-bad text { fill: var(--are-tours-ink); }
  & .are-tours-mk .are-tours-halo { fill: none; stroke: var(--are-tours-accent); stroke-width: 2; opacity: 0; transition: opacity .2s; }
  & .are-tours-mk:hover .are-tours-halo, & .are-tours-mk.is-hot .are-tours-halo, & .are-tours-mk:focus-visible .are-tours-halo { opacity: .9; }
  & .are-tours-mk.is-sel .are-tours-halo { opacity: 1; stroke-width: 3; }
  & .are-tours-mk .are-tours-tag { font: 600 11.5px system-ui; fill: var(--are-tours-ink); text-anchor: start; paint-order: stroke; stroke: var(--are-tours-land); stroke-width: 4px; stroke-linejoin: round; }
  & .are-tours-ghostmk .are-tours-tag { fill: var(--are-tours-mute); }
  & .are-tours-office rect { fill: var(--are-tours-ink); }
  & .are-tours-office text { font: 800 10px var(--are-tours-mono); fill: var(--are-tours-bg); text-anchor: middle; }
  & .are-tours-ghostmk circle { fill: none; stroke: var(--are-tours-faint); stroke-width: 2; stroke-dasharray: 3 3; }
}
.are-tours.is-off .are-tours-ants { animation-play-state: paused; }
.are-tours .are-tours-mtools { position: absolute; left: 12px; top: 12px; z-index: 2; }
.are-tours .are-tours-chip {
  display: inline-flex; align-items: center; gap: 8px; height: 32px; padding: 0 12px 0 8px; border-radius: 999px; border: 0;
  background: color-mix(in oklch, var(--are-tours-bg) 85%, transparent); box-shadow: inset 0 0 0 1px var(--are-tours-line2); backdrop-filter: blur(6px); font-weight: 600; font-size: 12px;
  & small { color: var(--are-tours-mute); font-weight: 500; }
  & i { width: 30px; height: 18px; border-radius: 9px; background: var(--are-tours-line2); position: relative; transition: background .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--are-tours-ink); transition: translate .35s var(--are-tours-spring); }
  &[aria-checked="true"] i { background: var(--are-tours-wait); }
  &[aria-checked="true"] i::after { translate: 12px 0; background: var(--are-tours-on); }
}
.are-tours .are-tours-legend {
  position: absolute; right: 12px; bottom: 12px; display: flex; gap: 12px; padding: 6px 10px; border-radius: 8px; font-size: 11px; color: var(--are-tours-mute);
  background: color-mix(in oklch, var(--are-tours-bg) 80%, transparent);
  & span { display: inline-flex; align-items: center; gap: 6px; }
  & span::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--are-tours-accent); }
  & .is-wait::before { background: var(--are-tours-wait); }
  & .is-bad::before { background: var(--are-tours-bad); }
}

/* ── timeline ─────────────────────────────────────── */
.are-tours .are-tours-time { grid-area: time; border-top: 1px solid var(--are-tours-line); background: var(--are-tours-bg); }
.are-tours .are-tours-tl { position: relative; padding: 8px 14px 10px; }
.are-tours .are-tours-axis { display: grid; grid-template-columns: 130px minmax(0, 1fr); font: 500 10px/1 var(--are-tours-mono); color: var(--are-tours-faint); height: 16px; }
.are-tours .are-tours-ticks { position: relative; & span { position: absolute; translate: -50% 0; } }
.are-tours .are-tours-tlrow {
  display: grid; grid-template-columns: 130px minmax(0, 1fr); align-items: center; height: 19px; cursor: pointer; border-radius: 5px;
  & > b { font-size: 11.5px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding-right: 10px; display: flex; gap: 6px; align-items: center; }
  & > b i { font: 750 10px/1 var(--are-tours-mono); color: var(--are-tours-mute); font-style: normal; }
  &:hover, &.is-hot { background: color-mix(in oklch, var(--are-tours-ink) 5%, transparent); }
  &.is-sel > b { color: var(--are-tours-accent); }
}
.are-tours .are-tours-track { position: relative; height: 13px; border-radius: 3px; background: repeating-linear-gradient(90deg, var(--are-tours-line) 0 1px, transparent 1px calc(100% / 6)); }
.are-tours .are-tours-win { position: absolute; top: 0; bottom: 0; border-radius: 3px; background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--are-tours-ink) 14%, transparent) 0 2px, transparent 2px 6px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--are-tours-ink) 16%, transparent); }
.are-tours .are-tours-blk { position: absolute; top: 2px; bottom: 2px; border-radius: 3px; background: var(--are-tours-accent); transition: left .5s var(--are-tours-ease), width .5s var(--are-tours-ease), background .3s; &.is-bad { background: var(--are-tours-bad); } }
.are-tours .are-tours-drv { position: absolute; top: 6px; height: 1px; background: var(--are-tours-mute); transition: left .5s var(--are-tours-ease), width .5s var(--are-tours-ease); }
.are-tours .are-tours-wt { position: absolute; top: 5px; height: 3px; background: repeating-linear-gradient(90deg, var(--are-tours-wait) 0 3px, transparent 3px 5px); transition: left .5s var(--are-tours-ease), width .5s var(--are-tours-ease); }

/* ── send dialog ─────────────────────────────────── */
.are-tours .are-tours-dlg {
  position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: color-mix(in oklch, black 45%, transparent);
  opacity: 0; visibility: hidden; transition: opacity .25s, visibility 0s linear .25s;
  &.is-open { opacity: 1; visibility: visible; transition: opacity .25s, visibility 0s; }
}
.are-tours .are-tours-card {
  width: min(560px, 100%); max-height: 100%; display: flex; flex-direction: column; border-radius: 16px; background: var(--are-tours-panel); box-shadow: 0 30px 80px -20px black, inset 0 0 0 1px var(--are-tours-line2);
  translate: 0 12px; scale: .98; transition: translate .5s var(--are-tours-spring), scale .5s var(--are-tours-spring);
  & header { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; border-bottom: 1px solid var(--are-tours-line); }
  & h3 { font-size: 15px; font-weight: 700; }
  & footer { display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--are-tours-line); }
}
.are-tours .are-tours-dlg.is-open .are-tours-card { translate: 0 0; scale: 1; }
.are-tours .are-tours-dbody { overflow-y: auto; padding: 14px 16px; display: grid; gap: 14px; }
.are-tours .are-tours-msg { padding: 12px; border-radius: 10px; background: var(--are-tours-bg); font: 12px/1.6 var(--are-tours-mono); white-space: pre-wrap; color: color-mix(in oklch, var(--are-tours-ink) 85%, transparent); max-height: 150px; overflow: auto; }
.are-tours .are-tours-rcpts {
  display: grid; gap: 4px;
  & li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 6px 8px; border-radius: 8px; background: var(--are-tours-bg); font-size: 12px; transition: background .3s; }
  & li > span:nth-child(2) { display: grid; min-width: 0; }
  & li small { color: var(--are-tours-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .are-tours-ch { font: 650 10px/1 var(--are-tours-mono); padding: 4px 6px; border-radius: 5px; background: var(--are-tours-raise); color: var(--are-tours-mute); }
  & .are-tours-state { font: 600 11px/1 var(--are-tours-mono); color: var(--are-tours-mute); display: inline-flex; align-items: center; gap: 6px; }
  & .are-tours-state.is-busy::before { content: ""; width: 10px; height: 10px; border-radius: 50%; border: 2px solid var(--are-tours-line2); border-top-color: var(--are-tours-accent); animation: are-tours-spin .7s linear infinite; }
  & .are-tours-state.is-done { color: var(--are-tours-accent); }
  & .are-tours-state.is-done::before { content: "✓"; }
}

.are-tours .are-tours-toasts { position: absolute; left: 50%; bottom: 16px; translate: -50% 0; z-index: 40; display: grid; gap: 8px; justify-items: center; pointer-events: none; width: max-content; max-width: calc(100% - 32px); }
.are-tours .are-tours-toast {
  pointer-events: auto; display: flex; align-items: center; gap: 10px; padding: 9px 10px 9px 14px; border-radius: 11px; background: var(--are-tours-ink); color: var(--are-tours-bg); font-size: 12.5px; font-weight: 550;
  box-shadow: 0 16px 34px -12px black; transition: opacity .25s, translate .45s var(--are-tours-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  &.is-gone { opacity: 0; translate: 0 8px; }
