  rowan: { a: '23 Rowan Crescent', s: 'Rowan Cres', hood: 'Ashgrove', p: 872000, bd: 4, x: 910, y: 520, w: [9.5, 11], agent: 'Hal Brennan', firm: 'Brennan Homes', conf: true, note: 'Dog in the garden until 10:00. Park on the crescent, not the drive.' },
  mariner: { a: "5 Mariner's Steps", s: "Mariner's Steps", hood: 'Quayside', p: 899000, bd: 3, x: 478, y: 856, w: [11, 13], agent: 'Open house', firm: 'Saltline Estates', conf: true, open: true, note: 'Open house, no appointment. Expect other buyers around midday.' },
  wren: { a: '9 Wren Mews', s: 'Wren Mews', hood: 'Ashgrove', p: 745000, bd: 3, x: 768, y: 486, w: [9, 17], agent: 'Vacant, lockbox', firm: 'Brightwell & Oduya', conf: true, vacant: true, note: 'Lockbox on the meter cupboard; code is in the office notes.' },
  larch: { a: '12 Larch Terrace', s: 'Larch Tce', hood: 'Fenwick Hill', p: 968000, bd: 3, x: 704, y: 236, w: [13, 15], agent: 'Mei Takahashi', firm: 'Fenwick & Vale', conf: false, note: 'Seller works from home and asks to see the garden studio last.' },
  fenwick: { a: '44 Fenwick Road', s: 'Fenwick Rd', hood: 'Fenwick Hill', p: 1149000, bd: 4, x: 870, y: 196, w: [12, 14], agent: 'Mei Takahashi', firm: 'Fenwick & Vale', conf: false, note: 'Above budget; the seller has hinted at offers around $1.08M.' },
  mill: { a: '102 Mill Lane', s: 'Mill Ln', hood: 'Millbrook', p: 629000, bd: 3, x: 478, y: 222, w: [10, 16], agent: 'Ross Adeyemi', firm: 'Millbrook Sales', conf: true, note: 'Townhouse with a small yard; a fallback if Thistle Close goes.' },
  alder: { a: '58 Alder Walk', s: 'Alder Walk', hood: 'Millbrook', p: 1045000, bd: 5, x: 280, y: 64, w: [11, 12.5], agent: 'Hal Brennan', firm: 'Brennan Homes', conf: false, note: 'Five bedrooms on Alder Common; only a 90-minute window.' },
