const S = {
  order: ['thistle', 'rowan', 'mariner', 'wren', 'larch', 'fenwick'], tray: ['mill', 'alder'],
  dur: { thistle: 30, rowan: 30, mariner: 20, wren: 20, larch: 30, fenwick: 30, mill: 30, alder: 30 },
  conf: Object.fromEntries(Object.entries(H).map(([k, v]) => [k, v.conf])),
  start: 9 * 60, traffic: false, sel: null, hot: null, open: null, lift: null, pane: 'stops', dlg: null, sent: {}, optimising: false,
