  let t = S.start, prev = OFFICE, totalDrive = 0, wait = 0, over = 0, conflicts = 0;
  const rows = order.map(id => {
    const h = H[id], d = drive(prev, h), arrive = t + d, w0 = h.w[0] * 60, w1 = h.w[1] * 60;
    const start = Math.max(arrive, w0), end = start + S.dur[id], late = Math.max(0, end - w1);
    totalDrive += d; wait += start - arrive; over += late; if (late) conflicts++;
    const r = { id, d, dist: km(prev, h), depart: t, arrive, start, end, wait: start - arrive, late };
    t = end; prev = h;
    return r;
