/* ── undo ─────────────────────────────────────────────────────────────── */
const undoStack = [];
const snap = () => JSON.stringify({ order: S.order, tray: S.tray, dur: S.dur, start: S.start, traffic: S.traffic, conf: S.conf });
function pushUndo() { undoStack.push(snap()); if (undoStack.length > 50) undoStack.shift(); }
function undo() {
