      <div class="are-tours-side"><button type="button" class="are-tours-dur" data-act="dur" data-id="${id}"></button><button type="button" class="are-tours-x" data-act="remove" data-id="${id}" aria-label="Remove ${esc(h.a)} from the tour" title="Remove (Delete)">${I.x}</button></div>
