  if (e.key === 'o' || e.key === 'O') optimise();
  else if (e.key === 't' || e.key === 'T') $('[data-act="traffic"]').click();
  else if (e.key === '+' || e.key === '=') $('[data-act="start"][data-v="15"]').click();
  else if (e.key === '-') $('[data-act="start"][data-v="-15"]').click();
});

/* ── boot ─────────────────────────────────────────────────────────────── */
new IntersectionObserver(es => es.forEach(en => root.classList.toggle('is-off', !en.isIntersecting))).observe(root);
new ResizeObserver(() => { if (root.isConnected && lastPlan) renderTimeline(lastPlan); }).observe(tl);
buildBase();
render();

css:
@property --are-offer-score { syntax: "<number>"; inherits: true; initial-value: 0; }

.are-offer {
  /* theme: override these four to re-skin */
  --are-offer-bg: oklch(0.952 0.008 75);
  --are-offer-ink: oklch(0.25 0.02 40);
  --are-offer-accent: oklch(0.47 0.14 22);
  --are-offer-paper: oklch(0.995 0.003 90);

  --are-offer-panel: color-mix(in oklch, var(--are-offer-bg) 45%, white);
  --are-offer-line: color-mix(in oklch, var(--are-offer-ink) 11%, transparent);
  --are-offer-line2: color-mix(in oklch, var(--are-offer-ink) 22%, transparent);
  --are-offer-mute: color-mix(in oklch, var(--are-offer-ink) 60%, var(--are-offer-bg));
  --are-offer-faint: color-mix(in oklch, var(--are-offer-ink) 36%, var(--are-offer-bg));
  --are-offer-wash: color-mix(in oklch, var(--are-offer-ink) 5%, var(--are-offer-bg));
  --are-offer-tint: color-mix(in oklch, var(--are-offer-accent) 10%, var(--are-offer-panel));
  --are-offer-on: oklch(0.99 0.004 80);
  --are-offer-good: oklch(0.52 0.11 155);
  --are-offer-warn: oklch(0.7 0.14 65);
  --are-offer-hi: oklch(0.93 0.11 95);
  --are-offer-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --are-offer-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --are-offer-ease: cubic-bezier(.2, .8, .2, 1);
  --are-offer-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-offer-h, 680px);
  container-type: inline-size; container-name: are-offer;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-offer-bg); color: var(--are-offer-ink); color-scheme: light;
  accent-color: var(--are-offer-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-offer-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-offer-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .42; }
  & h1, & h2, & h3, & h4, & p, & ul, & ol, & dl, & dd { margin: 0; }
  & ul, & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--are-offer-mono); padding: 2px 4px; min-width: 16px; text-align: center; border: 1px solid var(--are-offer-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-offer-mute); background: var(--are-offer-panel); }
}

.are-offer .are-offer-app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.08fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "top top" "panes panes" "form doc";
}

/* ── header ───────────────────────────────────────── */
.are-offer .are-offer-top { grid-area: top; display: flex; align-items: center; gap: 14px; padding: 10px 14px; border-bottom: 1px solid var(--are-offer-line); background: var(--are-offer-panel); }
.are-offer .are-offer-prop {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  & div { display: grid; min-width: 0; line-height: 1.3; }
  & b { font: 600 15px/1.25 var(--are-offer-serif); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & span:not(.are-offer-thumb) { font-size: 12px; color: var(--are-offer-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & em { font-style: normal; color: var(--are-offer-accent); font-weight: 600; }
}
.are-offer .are-offer-thumb { width: 44px; height: 35px; border-radius: 7px; overflow: hidden; flex: none; box-shadow: 0 0 0 1px var(--are-offer-line); & svg { width: 100%; height: 100%; display: block; stroke: none; } }
.are-offer .are-offer-acts { margin-left: auto; display: flex; gap: 8px; }
.are-offer .are-offer-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; border: 0; white-space: nowrap;
  background: var(--are-offer-panel); box-shadow: inset 0 0 0 1px var(--are-offer-line2); font-weight: 600; font-size: 12.5px;
  transition: background .2s, scale .3s var(--are-offer-spring);
  &:hover:where(:not(:disabled)) { background: var(--are-offer-wash); }
  &:active:where(:not(:disabled)) { scale: .96; }
}
.are-offer .are-offer-primary {
  background: var(--are-offer-accent); color: var(--are-offer-on); box-shadow: none;
  &:hover:where(:not(:disabled)) { background: color-mix(in oklch, var(--are-offer-accent) 85%, black); }
  & kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--are-offer-on) 40%, transparent); }
}
.are-offer .are-offer-panes { grid-area: panes; display: none; }

/* ── form ─────────────────────────────────────────── */
.are-offer .are-offer-form { grid-area: form; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 6px 18px 24px; }
.are-offer .are-offer-form[inert] { opacity: .55; filter: saturate(.6); }
.are-offer .are-offer-sec {
  padding: 14px 0 16px; border-bottom: 1px solid var(--are-offer-line); display: grid; gap: 12px;
  & h3 { display: flex; align-items: center; gap: 9px; font-size: 13.5px; font-weight: 720; letter-spacing: -.01em; }
  & h3 i { font: 700 11px/1 var(--are-offer-mono); font-style: normal; width: 20px; height: 20px; border-radius: 50%; display: grid; place-items: center; background: var(--are-offer-ink); color: var(--are-offer-on); }
}
.are-offer .are-offer-price {
  display: grid; grid-template-columns: 40px minmax(0, 1fr) 40px; gap: 6px; align-items: center;
  & > button { height: 48px; border-radius: 10px; border: 0; background: var(--are-offer-panel); box-shadow: inset 0 0 0 1px var(--are-offer-line2); display: grid; place-items: center; transition: scale .3s var(--are-offer-spring), background .2s; }
  & > button:hover { background: var(--are-offer-wash); }
  & > button:active { scale: .92; }
}
.are-offer .are-offer-pin {
  display: flex; align-items: center; gap: 4px; height: 48px; padding: 0 14px; border-radius: 10px; background: var(--are-offer-paper); box-shadow: inset 0 0 0 1px var(--are-offer-line2); transition: box-shadow .2s;
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--are-offer-accent); }
  & span { font: 500 22px/1 var(--are-offer-serif); color: var(--are-offer-mute); }
  & input { flex: 1 1 auto; min-width: 0; width: 100%; border: 0; background: none; outline: none; font: 500 26px/1 var(--are-offer-serif); letter-spacing: -.02em; font-variant-numeric: tabular-nums lining-nums; }
}
.are-offer .are-offer-ratio {
  display: grid; gap: 2px;
  & input { width: 100%; margin: 0; height: 18px; }
  & p { font-size: 12px; color: var(--are-offer-mute); font-variant-numeric: tabular-nums; }
  & p b { color: var(--are-offer-ink); }
}
.are-offer .are-offer-scale { display: flex; justify-content: space-between; font: 500 10px/1 var(--are-offer-mono); color: var(--are-offer-faint); padding: 0 2px; }
.are-offer .are-offer-sw {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 6px 0; border: 0; background: none; text-align: left;
  & > i { width: 34px; height: 20px; border-radius: 10px; background: var(--are-offer-line2); position: relative; flex: none; transition: background .25s; }
  & > i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--are-offer-paper); box-shadow: 0 1px 2px color-mix(in oklch, var(--are-offer-ink) 35%, transparent); transition: translate .35s var(--are-offer-spring); }
  &[aria-checked="true"] > i { background: var(--are-offer-accent); }
  &[aria-checked="true"] > i::after { translate: 14px 0; }
  & span { display: grid; line-height: 1.3; }
  & b { font-weight: 620; }
  & small { font-size: 11.5px; color: var(--are-offer-mute); }
  &.is-small { padding: 2px 0; }
}
.are-offer .are-offer-more { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--are-offer-ease); & > div { overflow: hidden; } }
.are-offer .are-offer-tog:has([aria-checked="true"]) .are-offer-more, .are-offer .are-offer-tog.is-open .are-offer-more { grid-template-rows: 1fr; }
.are-offer .are-offer-row {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; padding: 8px 0 2px 44px;
  & label { display: grid; gap: 4px; font-size: 12px; font-weight: 600; }
  &.is-loan { grid-template-columns: 120px minmax(0, 1fr); padding-left: 0; align-items: end; }
}
.are-offer .are-offer-in {
  display: flex; align-items: center; gap: 3px; height: 34px; padding: 0 9px; border-radius: 8px; background: var(--are-offer-paper); box-shadow: inset 0 0 0 1px var(--are-offer-line2); font-weight: 400;
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--are-offer-accent); }
  &:has([aria-invalid="true"]) { box-shadow: inset 0 0 0 1.5px oklch(0.55 0.18 28); }
  & span { color: var(--are-offer-mute); }
  & input { flex: 1 1 auto; min-width: 0; width: 100%; border: 0; background: none; outline: none; font: 600 13px/1 var(--are-offer-mono); font-variant-numeric: tabular-nums; }
}
.are-offer .are-offer-err { display: block; padding-left: 44px; font-size: 11.5px; color: oklch(0.52 0.18 28); font-weight: 600; &:empty { display: none; } }
.are-offer .are-offer-field { display: grid; gap: 6px; & .are-offer-lbl { font-size: 12px; font-weight: 600; } }
.are-offer .are-offer-seg {
  display: flex; padding: 3px; gap: 2px; border-radius: 10px; background: var(--are-offer-wash); box-shadow: inset 0 0 0 1px var(--are-offer-line);
  & button { flex: 1 1 0; display: grid; place-items: center; height: 34px; border: 0; border-radius: 7px; background: none; font-weight: 600; font-size: 12.5px; font-variant-numeric: tabular-nums; color: var(--are-offer-mute); line-height: 1.1; transition: background .2s, color .2s, box-shadow .2s; }
  & button small { font-size: 10.5px; font-weight: 500; }
  & button[aria-checked="true"] { background: var(--are-offer-paper); color: var(--are-offer-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--are-offer-ink) 18%, transparent), 0 0 0 1px var(--are-offer-line); }
}
.are-offer .are-offer-grid2 { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); gap: 10px; }
.are-offer .are-offer-step {
  display: flex; align-items: center; height: 40px; border-radius: 10px; background: var(--are-offer-paper); box-shadow: inset 0 0 0 1px var(--are-offer-line2);
  & button { width: 36px; height: 100%; border: 0; background: none; display: grid; place-items: center; color: var(--are-offer-mute); border-radius: 10px; }
  & button:hover:where(:not(:disabled)) { color: var(--are-offer-ink); background: var(--are-offer-wash); }
  & output { flex: 1 1 auto; display: grid; text-align: center; font-weight: 650; font-variant-numeric: tabular-nums; line-height: 1.15; }
  & output small { font-size: 10.5px; font-weight: 500; color: var(--are-offer-mute); }
}
.are-offer .are-offer-conds { display: grid; gap: 6px; }
.are-offer .are-offer-cond {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 11px; background: var(--are-offer-panel); box-shadow: inset 0 0 0 1px var(--are-offer-line);
  transition: background .25s, box-shadow .25s;
  &:has([aria-checked="true"]) { background: var(--are-offer-paper); box-shadow: inset 0 0 0 1px var(--are-offer-line2); }
  & .are-offer-sw { padding: 2px 0; }
  & .are-offer-days { display: flex; align-items: center; gap: 2px; font-variant-numeric: tabular-nums; transition: opacity .2s; }
  &:not(:has([aria-checked="true"])) .are-offer-days { opacity: .35; }
  & .are-offer-days button { width: 26px; height: 26px; border: 0; border-radius: 7px; background: var(--are-offer-wash); display: grid; place-items: center; }
  & .are-offer-days button:hover:where(:not(:disabled)) { background: color-mix(in oklch, var(--are-offer-ink) 10%, var(--are-offer-bg)); }
  & .are-offer-days output { min-width: 50px; text-align: center; font: 650 12px/1 var(--are-offer-mono); }
  & .are-offer-days svg { width: 13px; height: 13px; }
  & .are-offer-pts { font: 650 11px/1 var(--are-offer-mono); color: var(--are-offer-accent); }
}
.are-offer .are-offer-chips {
  display: flex; flex-wrap: wrap; gap: 6px;
  & button { height: 32px; padding: 0 12px 0 10px; border-radius: 16px; border: 0; background: var(--are-offer-panel); box-shadow: inset 0 0 0 1px var(--are-offer-line2); font-weight: 600; font-size: 12.5px; display: inline-flex; align-items: center; gap: 6px; transition: background .2s, color .2s, box-shadow .2s; }
  & button svg { width: 14px; height: 14px; transition: rotate .35s var(--are-offer-spring); }
  & button[aria-pressed="true"] { background: var(--are-offer-ink); color: var(--are-offer-on); box-shadow: none; }
  & button[aria-pressed="true"] svg { rotate: 45deg; }
}

/* ── document pane ───────────────────────────────── */
.are-offer .are-offer-docpane { grid-area: doc; min-height: 0; display: flex; flex-direction: column; border-left: 1px solid var(--are-offer-line); background: color-mix(in oklch, var(--are-offer-bg) 80%, var(--are-offer-ink) 6%); }
.are-offer .are-offer-strength {
  flex: none; display: grid; grid-template-columns: 112px minmax(0, 1fr); gap: 14px; align-items: center; padding: 12px 16px; border-bottom: 1px solid var(--are-offer-line); background: var(--are-offer-panel);
}
.are-offer .are-offer-gauge {
  position: relative; width: 112px; height: 64px;
  & svg { width: 112px; height: 64px; display: block; overflow: visible; }
  & .are-offer-track { fill: none; stroke: var(--are-offer-line); stroke-width: 9; stroke-linecap: round; }
  & .are-offer-arc { fill: none; stroke: var(--c); stroke-width: 9; stroke-linecap: round; stroke-dasharray: var(--are-offer-score) 100; transition: --are-offer-score .9s var(--are-offer-spring), stroke .4s; }
  & .are-offer-needle { transform-origin: 56px 56px; rotate: calc(var(--are-offer-score) * 1.8deg - 90deg); transition: --are-offer-score .9s var(--are-offer-spring); fill: var(--are-offer-paper); stroke: var(--are-offer-ink); stroke-width: 2.5; }
  & b { position: absolute; left: 0; right: 0; bottom: 2px; text-align: center; font: 750 22px/1 var(--are-offer-mono); font-variant-numeric: tabular-nums; letter-spacing: -.04em; }
}
.are-offer .are-offer-sinfo { display: grid; gap: 6px; min-width: 0; }
.are-offer .are-offer-shead { display: flex; align-items: baseline; gap: 8px; & b { font-size: 14px; font-weight: 720; } & span { font-size: 11.5px; color: var(--are-offer-mute); } }
.are-offer .are-offer-factors {
  display: flex; flex-wrap: wrap; gap: 4px;
  & li { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 7px; border-radius: 6px; font-size: 11px; background: var(--are-offer-wash); font-variant-numeric: tabular-nums; white-space: nowrap; }
  & li b { font: 700 10.5px/1 var(--are-offer-mono); }
  & li.is-up b { color: var(--are-offer-good); }
  & li.is-down b { color: var(--are-offer-accent); }
}
.are-offer .are-offer-docscroll { flex: 1 1 auto; min-height: 0; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; padding: 18px 22px 28px; }
.are-offer .are-offer-doc {
  position: relative; max-width: 620px; margin: 0 auto; padding: 30px 34px 34px; background: var(--are-offer-paper); border-radius: 3px;
  box-shadow: 0 1px 0 var(--are-offer-line), 0 18px 40px -22px color-mix(in oklch, var(--are-offer-ink) 45%, transparent);
  font: 13.5px/1.6 var(--are-offer-serif); color: color-mix(in oklch, var(--are-offer-ink) 92%, black);
  & header { display: grid; gap: 4px; padding-bottom: 14px; margin-bottom: 14px; border-bottom: 1.5px solid var(--are-offer-ink); }
  & h2 { font: 700 13px/1.2 system-ui; letter-spacing: .22em; text-transform: uppercase; text-align: center; }
  & header p { display: flex; justify-content: space-between; font: 11.5px/1.4 var(--are-offer-mono); color: var(--are-offer-mute); font-variant-numeric: tabular-nums; }
  & .are-offer-cl { padding: 4px 6px; margin: 0 -6px 6px; border-radius: 4px; text-wrap: pretty; }
  & .are-offer-cl b { font-weight: 700; }
  & .are-offer-cl em { font-style: normal; font-weight: 650; font-variant-numeric: tabular-nums lining-nums; }
  & .are-offer-cl.is-new { animation: are-offer-mark 1.6s var(--are-offer-ease); }
  & .are-offer-cl.is-off { color: var(--are-offer-faint); }
  & .are-offer-sub { padding-left: 18px; }
  & .are-offer-sigs { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 22px; margin-top: 26px; }
  & .are-offer-sig { display: grid; gap: 3px; font: 11px/1.3 system-ui; color: var(--are-offer-mute); }
  & .are-offer-sigline { height: 46px; border-bottom: 1px solid var(--are-offer-ink); display: flex; align-items: flex-end; }
  & .are-offer-sigline img, & .are-offer-sigline canvas { height: 44px; }
  & .are-offer-sigline span { font: italic 500 24px/1 var(--are-offer-serif); color: oklch(0.32 0.08 260); padding-bottom: 4px; }
  & .are-offer-stamp { position: absolute; right: 26px; top: 64px; padding: 6px 12px; border: 2.5px solid var(--are-offer-good); border-radius: 6px; color: var(--are-offer-good); font: 800 14px/1 system-ui; letter-spacing: .2em; rotate: -9deg; opacity: .85; animation: are-offer-stamp .5s var(--are-offer-spring); }
}
.are-offer .are-offer-dates {
  display: grid; grid-template-columns: repeat(var(--n), minmax(0, 1fr)); margin: 4px 0 14px; position: relative;
  &::before { content: ""; position: absolute; left: 8px; right: 8px; top: 7px; height: 2px; background: var(--are-offer-line2); }
  & li { position: relative; display: grid; justify-items: center; text-align: center; gap: 2px; font: 11px/1.25 system-ui; color: var(--are-offer-mute); }
  & li::before { content: ""; width: 12px; height: 12px; border-radius: 50%; background: var(--are-offer-paper); box-shadow: inset 0 0 0 2px var(--are-offer-ink); position: relative; }
  & li b { color: var(--are-offer-ink); font: 650 11.5px/1.2 var(--are-offer-mono); font-variant-numeric: tabular-nums; }
  & li:last-child::before { background: var(--are-offer-ink); }
}

/* ── review modal ────────────────────────────────── */
.are-offer .are-offer-modal {
  position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 18px; background: color-mix(in oklch, var(--are-offer-ink) 40%, transparent);
  opacity: 0; visibility: hidden; transition: opacity .25s, visibility 0s linear .25s;
  &.is-open { opacity: 1; visibility: visible; transition: opacity .25s, visibility 0s; }
}
.are-offer .are-offer-mcard {
  width: min(520px, 100%); max-height: 100%; display: flex; flex-direction: column; border-radius: 16px; background: var(--are-offer-panel); box-shadow: 0 30px 70px -20px color-mix(in oklch, var(--are-offer-ink) 60%, transparent);
  translate: 0 14px; transition: translate .5s var(--are-offer-spring);
  & header { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; border-bottom: 1px solid var(--are-offer-line); }
  & header h3 { font: 600 18px/1.2 var(--are-offer-serif); }
  & .are-offer-mbody { overflow-y: auto; padding: 14px 16px; display: grid; gap: 14px; }
  & footer { display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--are-offer-line); }
  & footer .are-offer-btn { flex: 1 1 0; height: 40px; }
}
.are-offer .are-offer-modal.is-open .are-offer-mcard { translate: 0 0; }
.are-offer .are-offer-x { width: 32px; height: 32px; border: 0; border-radius: 8px; background: none; display: grid; place-items: center; color: var(--are-offer-mute); &:hover { background: var(--are-offer-wash); color: var(--are-offer-ink); } }
.are-offer .are-offer-recap { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; font-variant-numeric: tabular-nums; & dt { color: var(--are-offer-mute); } & dd { font-weight: 620; } }
.are-offer .are-offer-pad {
  position: relative; height: 130px; border-radius: 12px; background: var(--are-offer-paper); box-shadow: inset 0 0 0 1px var(--are-offer-line2);
  & canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; cursor: crosshair; border-radius: 12px; }
  & .are-offer-padline { position: absolute; left: 20px; right: 20px; bottom: 30px; border-bottom: 1px dashed var(--are-offer-line2); pointer-events: none; }
