.are-offer .are-offer-toasts { position: absolute; left: 50%; bottom: 16px; translate: -50% 0; z-index: 40; display: grid; gap: 8px; justify-items: center; pointer-events: none; width: max-content; max-width: calc(100% - 32px); }
.are-offer .are-offer-toast {
