}

@media (prefers-reduced-motion: reduce) {
  .are-offer *, .are-offer *::before, .are-offer *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
  .are-offer .are-offer-gauge .are-offer-arc, .are-offer .are-offer-gauge .are-offer-needle { transition: none; }
  .are-offer .are-offer-doc .are-offer-cl.is-new { animation: none; background: color-mix(in oklch, var(--are-offer-hi) 50%, transparent); }
  .are-offer .are-offer-sent svg circle, .are-offer .are-offer-sent svg path { animation: none; stroke-dashoffset: 0; }
}

@keyframes are-offer-mark { 0%, 30% { background: var(--are-offer-hi); } 100% { background: transparent; } }
@keyframes are-offer-stamp { from { scale: 1.6; opacity: 0; } }
@keyframes are-offer-draw { to { stroke-dashoffset: 0; } }
@keyframes are-offer-prog { from { scale: 0 1; } }

