/* ── Brightwell & Oduya · offer builder ─────────────────────────────────
   The terms on the left are one state object. strength() turns it into
   integer points per factor, so the breakdown chips always add up to the
   score on the gauge. The document is rendered clause by clause; a clause
   whose text changed is swapped in and highlighted, nothing else moves. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
const UID = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { const o = el.id, n = o + '-' + UID; el.id = n; $$(`[aria-labelledby="${o}"]`).forEach(x => x.setAttribute('aria-labelledby', n)); });
$('[data-modk]').textContent = MAC ? '⌘↵' : 'Ctrl ↵';

const I = {
  minus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h12"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  done: '<svg viewBox="0 0 56 56" aria-hidden="true"><circle cx="28" cy="28" r="22"/><path d="m18 29 7 7 13-15"/></svg>',
};

/* ── terms ────────────────────────────────────────────────────────────── */
const ASK = 872000, TODAY = Date.UTC(2026, 9, 2);
const CONDS = [
  { k: 'insp', n: 'Home inspection', min: 5, max: 21, d: 10, pts: d => -Math.round(2 + d / 2.5), txt: d => `a home inspection satisfactory to Buyer, completed within ${d} days of acceptance` },
  { k: 'fin', n: 'Loan approval', min: 10, max: 45, d: 21, loan: true, pts: d => -Math.round(3 + d / 6), txt: d => `Buyer obtaining final loan approval within ${d} days of acceptance` },
  { k: 'appr', n: 'Appraisal at or above price', min: 7, max: 21, d: 14, loan: true, pts: () => -5, txt: d => `the Property appraising at or above the purchase price within ${d} days of acceptance` },
  { k: 'sale', n: 'Sale of our current home', min: 15, max: 60, d: 30, pts: () => -15, txt: d => `the sale of Buyer's home at 14 Pell Street closing within ${d} days of acceptance` },
  { k: 'title', n: 'Title & HOA document review', min: 3, max: 10, d: 5, pts: () => -2, txt: d => `Buyer's review of the title report and HOA documents within ${d} days of receipt` },
];
const INCL = [['fridge', 'Refrigerator'], ['wd', 'Washer & dryer'], ['blinds', 'Window coverings'], ['shed', 'Garden shed'], ['tub', 'Hot tub'], ['patio', 'Patio furniture']];
const DEPS = [1, 2, 3, 5], EXPS = [24, 48, 72];
const fresh = () => ({
  price: 885000, esc: false, escBy: 5000, escCap: 915000, dep: 3, fin: 'loan', down: 20, preapp: true,
  cond: { insp: { on: true, d: 10 }, fin: { on: true, d: 21 }, appr: { on: false, d: 14 }, sale: { on: false, d: 30 }, title: { on: true, d: 5 } },
  close: 30, exp: 48, rentback: false, incl: ['fridge', 'wd', 'blinds'],
});
let T = fresh();
const S = { pane: 'terms', modal: null, agree: false, typed: '', strokes: [], sent: false, rev: 1, sig: null };

/* ── helpers ──────────────────────────────────────────────────────────── */
const usd = n => '$' + Math.round(n).toLocaleString('en-US');
const day = n => new Date(TODAY + n * 864e5).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' });
const longDay = n => new Date(TODAY + n * 864e5).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
const accept = () => T.exp / 24;        /* latest acceptance, in days from today */
function words(n) {
  const a = ['', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
  const b = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
  const t = x => x < 20 ? a[x] : b[Math.floor(x / 10)] + (x % 10 ? '-' + a[x % 10] : '');
  const h = x => x >= 100 ? a[Math.floor(x / 100)] + ' hundred' + (x % 100 ? ' ' + t(x % 100) : '') : t(x);
  const m = Math.floor(n / 1e6), k = Math.floor(n % 1e6 / 1000), r = n % 1000, out = [];
  if (m) out.push(h(m) + ' million'); if (k) out.push(h(k) + ' thousand'); if (r) out.push(h(r));
  return out.join(' ') || 'zero';
}
const condOn = c => T.cond[c.k].on && !(c.loan && T.fin === 'cash');

/* ── strength: integer points per factor, summed onto a base of 50 ────── */
function strength() {
  const f = [];
  const r = T.price / ASK, pp = clamp(Math.round((r - 1) * 400), -30, 30);
  f.push([pp >= 0 ? `${((r - 1) * 100).toFixed(1)}% over asking` : `${((1 - r) * 100).toFixed(1)}% under asking`, pp]);
  if (T.esc && T.escCap > T.price) f.push(['Escalation clause', 6]);
  f.push([`${T.dep}% deposit`, { 1: -3, 2: 0, 3: 3, 5: 6 }[T.dep]]);
  if (T.fin === 'cash') f.push(['Cash, no loan', 10]);
  else { f.push([T.preapp ? 'Pre-approved' : 'No pre-approval', T.preapp ? 2 : -6]); f.push([`${T.down}% down`, T.down >= 20 ? 2 : -2]); }
  CONDS.forEach(c => { if (condOn(c)) f.push([c.n, c.pts(T.cond[c.k].d)]); });
  f.push([`Close in ${T.close} days`, T.close <= 21 ? 5 : T.close <= 30 ? 3 : T.close <= 45 ? 0 : -4]);
  if (T.rentback) f.push(['Rent-back for seller', 3]);
  if (T.incl.length > 3) f.push([`${T.incl.length} included items`, -(T.incl.length - 3)]);
  f.push([`${T.exp}h to respond`, { 24: 2, 48: 0, 72: -2 }[T.exp]]);
  const sum = f.reduce((s, x) => s + x[1], 0), score = clamp(50 + sum, 0, 100);
  const label = score >= 80 ? 'Very strong' : score >= 60 ? 'Strong' : score >= 40 ? 'Competitive' : 'Weak';
  const color = score >= 60 ? 'var(--are-offer-good)' : score >= 40 ? 'var(--are-offer-warn)' : 'var(--are-offer-accent)';
  return { f, sum, score, label, color };
}

/* ── undo ─────────────────────────────────────────────────────────────── */
const undoStack = [];
function pushUndo() { undoStack.push(JSON.stringify(T)); if (undoStack.length > 60) undoStack.shift(); }
function undo() {
  const s = undoStack.pop();
  if (!s || S.sent) return;
  T = JSON.parse(s); fillInputs(); render(); toast('Undone');
}

/* ── form ─────────────────────────────────────────────────────────────── */
const form = $('[data-form]'), F = n => form.elements[n];
const parseNum = v => { const n = parseFloat(String(v).replace(/[^0-9.]/g, '')); return isFinite(n) ? n : NaN; };
function fillInputs(except) {
  const set = (n, v) => { if (F(n) !== except && doc.activeElement !== F(n)) F(n).value = v; };
  set('price', T.price.toLocaleString('en-US')); set('ratio', (T.price / ASK * 100).toFixed(1));
  set('escBy', T.escBy.toLocaleString('en-US')); set('escCap', T.escCap.toLocaleString('en-US')); set('down', T.down);
}
function renderForm() {
  const st = strength();
  const r = T.price / ASK;
  $('[data-ratio]').innerHTML = `<b>${(r * 100).toFixed(1)}%</b> of asking · ${T.price >= ASK ? usd(T.price - ASK) + ' over' : usd(ASK - T.price) + ' under'} · <b>${words(T.price)}</b> dollars`;
  $$('[data-act="price"]').forEach(b => { const v = +b.dataset.v, lim = v < 0 ? T.price <= 600000 : T.price >= 1200000; b.disabled = lim; b.title = lim ? 'Outside the range for this home' : (v < 0 ? 'Lower by $5,000' : 'Raise by $5,000'); });
  $$('[data-act="sw"]').forEach(b => b.setAttribute('aria-checked', !!T[b.dataset.v]));
  $('[data-escerr]').textContent = T.esc && T.escCap <= T.price ? 'The cap must be above your offer price' : '';
  F('escCap').toggleAttribute('aria-invalid', T.esc && T.escCap <= T.price);
  $('[data-deps]').innerHTML = DEPS.map(d => `<button type="button" role="radio" data-act="dep" data-v="${d}" aria-checked="${T.dep === d}" tabindex="${T.dep === d ? 0 : -1}">${d}%<small>${usd(T.price * d / 100)}</small></button>`).join('');
  $('[data-fins]').innerHTML = [['cash', 'Cash'], ['loan', 'Mortgage']].map(([k, l]) => `<button type="button" role="radio" data-act="fin" data-v="${k}" aria-checked="${T.fin === k}" tabindex="${T.fin === k ? 0 : -1}">${l}<small>${k === 'cash' ? 'proof of funds' : usd(T.price * (1 - T.down / 100)) + ' loan'}</small></button>`).join('');
  $('[data-tog="loan"]').classList.toggle('is-open', T.fin === 'loan');
  $('[data-tog="loan"]').inert = T.fin !== 'loan';
  $('[data-conds]').innerHTML = CONDS.map(c => {
    const s = T.cond[c.k], na = c.loan && T.fin === 'cash', on = condOn(c);
    return `<li class="are-offer-cond"><button type="button" class="are-offer-sw is-small" role="switch" data-act="cond" data-v="${c.k}" aria-checked="${on}" ${na ? 'disabled title="Not needed when paying cash"' : ''}><i></i><span><b>${c.n}</b><small>${na ? 'Not needed with cash' : on ? `<span class="are-offer-pts">${c.pts(s.d)} pts</span> · by ${day(accept() + s.d)}` : 'Waived'}</small></span></button>
      <div class="are-offer-days"><button type="button" data-act="cdays" data-k="${c.k}" data-v="-1" aria-label="${c.n}: one day less" ${!on || s.d <= c.min ? `disabled title="${!on ? 'Turn this condition on first' : 'Shortest allowed: ' + c.min + ' days'}"` : ''}>${I.minus}</button><output>${s.d} days</output><button type="button" data-act="cdays" data-k="${c.k}" data-v="1" aria-label="${c.n}: one day more" ${!on || s.d >= c.max ? `disabled title="${!on ? 'Turn this condition on first' : 'Longest allowed: ' + c.max + ' days'}"` : ''}>${I.plus}</button></div></li>`;
  }).join('');
  $('[data-close]').innerHTML = `${T.close} days<small>${day(accept() + T.close)}</small>`;
  $$('[data-act="close"]').forEach(b => { const v = +b.dataset.v, lim = v < 0 ? T.close <= 15 : T.close >= 75; b.disabled = lim; b.title = lim ? (v < 0 ? 'Lenders need at least 15 days' : 'Seventy-five days is the longest this seller will hold') : (v < 0 ? 'Five days sooner' : 'Five days later'); });
  $('[data-exps]').innerHTML = EXPS.map(h => `<button type="button" role="radio" data-act="exp" data-v="${h}" aria-checked="${T.exp === h}" tabindex="${T.exp === h ? 0 : -1}">${h} h<small>${day(h / 24)} 17:00</small></button>`).join('');
  $('[data-incl]').innerHTML = INCL.map(([k, l]) => `<button type="button" data-act="incl" data-v="${k}" aria-pressed="${T.incl.includes(k)}">${I.plus}${l}</button>`).join('');
  return st;
}
let pre = null;
form.addEventListener('focusin', e => { if (e.target.matches('input')) pre = JSON.stringify(T); });
form.addEventListener('pointerdown', e => { if (e.target.matches('input[type="range"]')) pre = JSON.stringify(T); });
form.addEventListener('input', e => {
  const t = e.target, v = parseNum(t.value);
  if (t.name === 'price') { if (v >= 600000 && v <= 1200000) { T.price = Math.round(v); t.removeAttribute('aria-invalid'); } else t.setAttribute('aria-invalid', 'true'); }
  else if (t.name === 'ratio') T.price = Math.round(ASK * v / 100 / 1000) * 1000;
  else if (t.name === 'escBy') T.escBy = clamp(Math.round(v || 0), 0, 100000);
  else if (t.name === 'escCap') T.escCap = clamp(Math.round(v || 0), 0, 2000000);
  else if (t.name === 'down') { if (v >= 5 && v <= 95) T.down = Math.round(v * 10) / 10; }
  fillInputs(t); render();
});
form.addEventListener('change', () => { fillInputs(); render(); const now = JSON.stringify(T); if (pre && pre !== now) undoStack.push(pre); pre = now; syncUndo(); });
form.addEventListener('keydown', e => {
  if (e.target.name === 'price' && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) { e.preventDefault(); step('price', e.key === 'ArrowUp' ? 1000 : -1000); }
  if (e.key === 'Enter' && e.target.matches('input:not([type="range"])')) { e.preventDefault(); e.target.blur(); }
});
form.addEventListener('submit', e => e.preventDefault());
function step(k, by) { pushUndo(); T[k] = clamp(T[k] + by, 600000, 1200000); fillInputs(); render(); }

/* ── document ─────────────────────────────────────────────────────────── */
const docEl = $('[data-doc]'), docScroll = $('[data-docscroll]');
let prevClauses = {};
function clauses() {
  const conds = CONDS.filter(condOn), A = accept(), loan = T.price * (1 - T.down / 100), incl = INCL.filter(i => T.incl.includes(i[0])).map(i => i[1].toLowerCase());
  const c = {};
  c.parties = `<b>1. Parties.</b> Ada Okonkwo and Tunde Okonkwo (“Buyer”) offer to buy from the owner of record (“Seller”) the land and home at 23 Rowan Crescent, Ashgrove, Port Alder (“Property”).`;
  c.price = `<b>2. Price.</b> <em>${usd(T.price)}</em> (${words(T.price)} dollars), which is ${(T.price / ASK * 100).toFixed(1)}% of the list price of ${usd(ASK)}.`;
  c.esc = T.esc ? `<b>2a. Escalation.</b> If Seller receives a bona fide competing offer, Buyer will pay <em>${usd(T.escBy)}</em> more than that offer's price, up to a maximum of <em>${usd(T.escCap)}</em>${T.escCap <= T.price ? ' <span style="color:var(--are-offer-accent)">(cap is below the offer price and has no effect)</span>' : ''}.` : '';
  c.deposit = `<b>3. Earnest money.</b> <em>${usd(T.price * T.dep / 100)}</em> (${T.dep}% of the price), paid to Port Alder Title Co. within three business days of acceptance and credited to Buyer at closing.`;
  c.finance = T.fin === 'cash' ? `<b>4. Payment.</b> Buyer will pay the full price in cash at closing; proof of funds is attached.`
    : `<b>4. Financing.</b> Buyer will pay <em>${usd(T.price - loan)}</em> (${T.down}%) down and borrow <em>${usd(loan)}</em> on a conventional loan.${T.preapp ? ' A pre-approval letter from Tallow Credit Union dated 28 September 2026 is attached.' : ''}`;
  c.cond = conds.length ? `<b>5. Conditions.</b> This offer is subject to ${conds.map((x, i) => `(${'abcde'[i]}) ${x.txt(T.cond[x.k].d)}, by <em>${day(A + T.cond[x.k].d)}</em>`).join('; ')}. If a condition is not met or waived in writing by its date, Buyer may cancel and the earnest money is returned.`
    : `<b>5. Conditions.</b> None. Buyer waives inspection, financing, appraisal and review contingencies.`;
  c.close = `<b>6. Closing.</b> On or before <em>${longDay(A + T.close)}</em>, ${T.close} days after acceptance. ${T.rentback ? 'Seller may stay in the Property for three days after closing at no charge.' : 'Possession passes to Buyer at closing.'}`;
  c.incl = `<b>7. Included items.</b> ${incl.length ? 'The sale includes the ' + incl.join(', ').replace(/, ([^,]*)$/, ' and $1') + ', in working order.' : 'No personal property is included.'}`;
  c.exp = `<b>8. Expiry.</b> This offer lapses at 17:00 on <em>${longDay(T.exp / 24)}</em> unless Seller accepts it in writing before then.`;
  return c;
}
function renderDoc(animate) {
  const c = clauses(), A = accept();
  if (!docEl.firstChild) {
