css:
@property --are-pipeline-fill { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.are-pipeline {
  /* theme: override these four to re-skin */
  --are-pipeline-bg: oklch(0.185 0.018 165);
  --are-pipeline-ink: oklch(0.95 0.012 150);
  --are-pipeline-accent: oklch(0.84 0.13 86);
  --are-pipeline-col: oklch(0.215 0.018 165);

  --are-pipeline-card: color-mix(in oklch, var(--are-pipeline-col) 82%, white 6%);
  --are-pipeline-raise: color-mix(in oklch, var(--are-pipeline-col) 70%, white 10%);
  --are-pipeline-line: color-mix(in oklch, var(--are-pipeline-ink) 10%, transparent);
  --are-pipeline-line2: color-mix(in oklch, var(--are-pipeline-ink) 18%, transparent);
  --are-pipeline-mute: color-mix(in oklch, var(--are-pipeline-ink) 58%, var(--are-pipeline-bg));
  --are-pipeline-faint: color-mix(in oklch, var(--are-pipeline-ink) 34%, var(--are-pipeline-bg));
  --are-pipeline-on: oklch(0.22 0.04 85);
  --are-pipeline-bad: oklch(0.7 0.16 28);
  --are-pipeline-s0: oklch(0.72 0.03 250);
  --are-pipeline-s1: oklch(0.74 0.09 195);
  --are-pipeline-s2: oklch(0.8 0.13 75);
  --are-pipeline-s3: oklch(0.72 0.14 35);
  --are-pipeline-s4: oklch(0.78 0.15 150);
  --are-pipeline-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --are-pipeline-ease: cubic-bezier(.2, .8, .2, 1);
  --are-pipeline-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-pipeline-h, 680px);
  container-type: inline-size; container-name: are-pipeline;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-pipeline-bg); color: var(--are-pipeline-ink); color-scheme: dark;
  accent-color: var(--are-pipeline-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-pipeline-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-pipeline-accent); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & h4, & p, & ul, & ol, & dl, & dd { margin: 0; }
  & ul, & ol { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--are-pipeline-mono); padding: 2px 4px; min-width: 16px; text-align: center; border: 1px solid var(--are-pipeline-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-pipeline-mute); background: var(--are-pipeline-col); }
}

.are-pipeline .are-pipeline-app {
  position: relative; height: 100%; display: grid; grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto minmax(0, 1fr); grid-template-areas: "top" "kpis" "main";
}

/* ── header ───────────────────────────────────────── */
.are-pipeline .are-pipeline-top { grid-area: top; display: flex; align-items: center; gap: 12px; padding: 10px 14px; border-bottom: 1px solid var(--are-pipeline-line); }
.are-pipeline .are-pipeline-brand {
  display: flex; align-items: baseline; gap: 8px; white-space: nowrap; margin-right: 4px;
  & svg { width: 20px; height: 20px; align-self: center; color: var(--are-pipeline-accent); }
  & b { font-weight: 760; letter-spacing: -.01em; }
