}
.are-pipeline .are-pipeline-views, .are-pipeline .are-pipeline-seg {
  display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--are-pipeline-col); box-shadow: inset 0 0 0 1px var(--are-pipeline-line);
  & button { display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px; border: 0; border-radius: 6px; background: none; font-weight: 600; font-size: 12px; color: var(--are-pipeline-mute); transition: background .2s, color .2s; }
