  &:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--are-pipeline-accent); }
  & svg { color: var(--are-pipeline-mute); width: 15px; height: 15px; }
  & input { flex: 1 1 auto; min-width: 0; border: 0; background: none; outline: none; height: 100%; font-size: 12.5px; }
  & input::-webkit-search-cancel-button { filter: invert(1) opacity(.5); }
}
