@property --are-rentroll-got { syntax: "<percentage>"; inherits: true; initial-value: 0%; }

.are-rentroll {
  /* theme: override these four to re-skin */
  --are-rentroll-bg: oklch(0.205 0.014 55);
  --are-rentroll-ink: oklch(0.94 0.022 85);
  --are-rentroll-accent: oklch(0.73 0.13 55);
