  --are-rentroll-line: color-mix(in oklch, var(--are-rentroll-ink) 10%, transparent);
  --are-rentroll-line2: color-mix(in oklch, var(--are-rentroll-ink) 18%, transparent);
  --are-rentroll-mute: color-mix(in oklch, var(--are-rentroll-ink) 58%, var(--are-rentroll-bg));
  --are-rentroll-faint: color-mix(in oklch, var(--are-rentroll-ink) 34%, var(--are-rentroll-bg));
  --are-rentroll-on: oklch(0.22 0.03 55);
  --are-rentroll-paid: oklch(0.7 0.075 150);
  --are-rentroll-late: oklch(0.66 0.17 25);
  --are-rentroll-notice: oklch(0.8 0.12 82);
  --are-rentroll-vacant: oklch(0.74 0.08 230);
  --are-rentroll-turn: oklch(0.7 0.08 305);
  --are-rentroll-shop: oklch(0.78 0.06 70);
  --are-rentroll-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --are-rentroll-ease: cubic-bezier(.2, .8, .2, 1);
  --are-rentroll-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-rentroll-h, 680px);
  container-type: inline-size; container-name: are-rentroll;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-rentroll-bg); color: var(--are-rentroll-ink); color-scheme: dark;
  accent-color: var(--are-rentroll-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-rentroll-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-rentroll-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
