  & kbd { font: 600 10px/1 var(--are-rentroll-mono); padding: 2px 4px; min-width: 16px; text-align: center; border: 1px solid var(--are-rentroll-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-rentroll-mute); background: var(--are-rentroll-panel); }
}

.are-rentroll .are-rentroll-app {
