/* ── The Halden · stacking-plan rent roll ───────────────────────────────
   Each unit carries a ledger of dated charges and payments. Whether a unit
   is late in a given month, its balance, the month's billed and collected
   totals and the arrears are all folded from those ledgers, so recording a
   payment changes the cell, the panel and the KPIs together. The plan is a
   CSS grid whose floor rows are subgrids; lenses only change --c and text. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

const I = {
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M19 12H5m6-6-6 6 6 6"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
  bldg: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="3" width="14" height="18" rx="1"/><path d="M9 7h2M13 7h2M9 11h2M13 11h2M9 15h2M13 15h2"/></svg>',
};
const MONTHS = ['Aug 2026', 'Sep 2026', 'Oct 2026'], MS = ['Aug', 'Sep', 'Oct'];
const COLS = [['A', '1 bd', 620, 2050], ['B', '2 bd', 940, 2780], ['C', '2 bd', 980, 2860], ['D', '1 bd', 640, 2090], ['E', 'Studio', 470, 1640], ['F', '3 bd', 1260, 3620]];
const FIRST = ['Maya', 'Idris', 'Hannah', 'Tomasz', 'Leila', 'Owen', 'Chiara', 'Kwame', 'Signe', 'Rafael', 'Noor', 'Ben', 'Aiko', 'Marta', 'Felix', 'Zara', 'Ruth', 'Dev', 'Elif', 'Callum', 'Ines', 'Jonah', 'Freya', 'Musa'];
const LAST = ['Ferreira', 'Halvorsen', 'Abara', 'Lindqvist', 'Moreau', 'Okafor', 'Brandt', 'Sato', 'Novak', 'Quinn', 'Haddad', 'Pryce', 'Castell', 'Mensah', 'Varga', 'Rao', 'Byrne', 'Ostrowski', 'Tanabe', 'Whitfield', 'Ortega', 'Hollis'];
const ST = { paid: ['Paid', 'paid'], late: ['Late', 'late'], notice: ['Notice', 'notice'], vacant: ['Vacant', 'vacant'], turn: ['Make-ready', 'turn'], shop: ['Shop', 'shop'] };
const color = k => `var(--are-rentroll-${k})`;
const money = n => (n < 0 ? '−$' : '$') + Math.abs(Math.round(n)).toLocaleString('en-US');
const kfmt = n => '$' + (n / 1000).toFixed(n >= 100000 ? 0 : 1) + 'k';

/* ── the building ─────────────────────────────────────────────────────── */
const U = [];
for (let f = 8; f >= 1; f--) COLS.forEach(([col, type, sf, base], c) => {
  const id = String(f * 100 + c + 1), rent = Math.round((base + (f - 1) * 25 + (c === 5 ? 150 : 0)) / 5) * 5;
  const k = f * 7 + c * 13, end = ((f * 5 + c * 7) % 15) + 1;
  U.push({ id, f, c, col, type, sf, rent, tenant: FIRST[k % FIRST.length] + ' ' + LAST[(k * 3 + 1) % LAST.length], kind: 'occ', end, ledger: [], log: [['Sep 1', 'Lease auto-renewal reviewed']], listed: false, checks: null });
});
U.push({ id: 'R1', f: 0, c: 0, col: 'R1', type: 'Café', sf: 1840, rent: 6400, tenant: 'Fold Coffee', kind: 'shop', end: 38, ledger: [], log: [] });
U.push({ id: 'R2', f: 0, c: 3, col: 'R2', type: 'Retail', sf: 1520, rent: 5250, tenant: 'Mercer Cycles', kind: 'shop', end: 22, ledger: [], log: [] });
const byId = Object.fromEntries(U.map(u => [u.id, u]));
const set = (id, o) => Object.assign(byId[id], o);
set('502', { kind: 'vacant', tenant: '', vacantDays: 21, listed: true, prev: 'Sasha Imrie' });
set('105', { kind: 'vacant', tenant: '', vacantDays: 9, listed: true, prev: 'Owen Quinn' });
set('704', { kind: 'turn', tenant: '', vacantDays: 5, prev: 'Ruth Abara', checks: { Paint: true, 'Deep clean': true, Flooring: false, 'Move-in inspection': false } });
set('304', { kind: 'notice', moveOut: '31 Oct', end: 1 });
set('601', { kind: 'notice', moveOut: '15 Nov', end: 2 });
set('806', { kind: 'notice', moveOut: '30 Nov', end: 2 });
/* ledgers: three months of rent; a few tenants behind */
const short = { '203': { 2: 0 }, '405': { 1: 0.78, 2: 0 }, '702': { 2: 0 }, '106': { 2: 0.36 } };
U.forEach(u => {
  if (u.kind === 'vacant' || u.kind === 'turn') return;
  for (let m = 0; m < 3; m++) {
    u.ledger.push({ m, d: 1, what: 'Rent', amt: u.rent });
    const part = short[u.id] && short[u.id][m] != null ? short[u.id][m] : 1;
    if (part > 0) u.ledger.push({ m, d: 1 + ((u.f + u.c + m) % 4), what: part < 1 ? 'Partial payment' : 'Payment · ACH', amt: -Math.round(u.rent * part) });
  }
  if (short[u.id]) u.log.unshift(['Oct 2', 'Rent reminder emailed']);
});

/* ── state & derived values ───────────────────────────────────────────── */
const S = { month: 2, lens: 'status', sel: null, focus: '801', hide: new Set(), pane: 'stack', form: null, f: { method: 'ACH', amt: '', err: '', pct: 3, name: '', start: 'Nov 1' } };
const balance = (u, m = S.month) => u.ledger.filter(e => e.m <= m).reduce((s, e) => s + e.amt, 0);
function status(u, m = S.month) {
  if (u.kind === 'shop') return 'shop';
  if (u.kind === 'vacant' || u.kind === 'turn') return u.kind;
  if (balance(u, m) > 0) return 'late';
  return u.kind === 'notice' ? 'notice' : 'paid';
}
const occupied = u => u.kind === 'occ' || u.kind === 'notice';
function totals(m = S.month) {
  const billed = U.reduce((s, u) => s + u.ledger.filter(e => e.m === m && e.amt > 0).reduce((a, e) => a + e.amt, 0), 0);
  const got = -U.reduce((s, u) => s + u.ledger.filter(e => e.m === m && e.amt < 0).reduce((a, e) => a + e.amt, 0), 0);
  const res = U.filter(u => u.kind !== 'shop'), occ = res.filter(occupied).length;
  const late = U.filter(u => balance(u, m) > 0), arrears = late.reduce((s, u) => s + balance(u, m), 0);
  const exp = res.filter(u => occupied(u) && u.end <= 3).length;
  const ppsf = res.filter(occupied).reduce((s, u) => s + u.rent, 0) / res.filter(occupied).reduce((s, u) => s + u.sf, 0);
  return { billed, got, occ, n: res.length, late, arrears, exp, ppsf };
}
const M12 = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const endLabel = u => { const t = 2026 * 12 + 9 + u.end; return M12[t % 12] + ' ' + String(Math.floor(t / 12)).slice(2); };

/* ── lenses ───────────────────────────────────────────────────────────── */
const LENSES = [['status', 'Status'], ['rent', 'Rent / ft²'], ['expiry', 'Lease end']];
const EXP = [['e2', '≤ 2 mo', 'late', u => u.end <= 2], ['e5', '3–5 mo', 'notice', u => u.end > 2 && u.end <= 5], ['e11', '6–11 mo', 'paid', u => u.end > 5 && u.end < 12], ['e12', '12 mo +', 'vacant', u => u.end >= 12]];
const res = U.filter(u => u.kind !== 'shop');
const PP = res.map(u => u.rent / u.sf), PMIN = Math.min(...PP), PMAX = Math.max(...PP);
function look(u) {
  const st = status(u);
  if (S.lens === 'status') return { c: color(ST[st][1]), key: st, v: u.kind === 'shop' ? money(u.rent) + ' · ' + u.type.toLowerCase() + ' lease' : st === 'vacant' ? (u.listed ? 'Listed · ' : '') + u.vacantDays + 'd empty' : st === 'turn' ? Object.values(u.checks).filter(Boolean).length + ' of 4 ready' : money(u.rent), tag: st === 'paid' || st === 'shop' ? '' : ST[st][0] };
  if (S.lens === 'rent') {
    const p = u.rent / u.sf, t = u.kind === 'shop' ? 1 : (p - PMIN) / (PMAX - PMIN);
    return { c: `color-mix(in oklch, var(--are-rentroll-accent) ${Math.round(20 + t * 80)}%, var(--are-rentroll-vacant))`, key: 'r', v: '$' + p.toFixed(2) + '/ft²', tag: '' };
  }
  if (!occupied(u) && u.kind !== 'shop') return { c: 'var(--are-rentroll-faint)', key: 'vac', v: 'Vacant', tag: '' };
  const e = EXP.find(x => x[3](u));
  return { c: color(e[2]), key: e[0], v: 'Ends ' + endLabel(u), tag: u.end <= 2 ? u.end + ' mo' : '' };
}

/* ── header, KPIs, legend ─────────────────────────────────────────────── */
function renderTop() {
  $('[data-lenses]').innerHTML = LENSES.map(([k, l]) => `<button type="button" role="radio" data-act="lens" data-v="${k}" aria-checked="${S.lens === k}" tabindex="${S.lens === k ? 0 : -1}">${l}</button>`).join('');
  $('[data-month]').textContent = MONTHS[S.month];
  $$('[data-act="month"]').forEach(b => { const v = +b.dataset.v, lim = v < 0 ? S.month === 0 : S.month === 2; b.disabled = lim; b.title = lim ? (v < 0 ? 'The ledger starts in August' : 'October is the current month') : (v < 0 ? 'Previous month' : 'Next month'); });
  const T = totals(), pct = T.got / T.billed * 100;
  $('[data-kpis]').innerHTML = `
    <dl class="are-rentroll-kpi"><dt>Occupancy</dt><dd>${(T.occ / T.n * 100).toFixed(1)}%</dd><small>${T.occ} of ${T.n} homes let</small></dl>
    <dl class="are-rentroll-kpi"><dt>Collected · ${MS[S.month]}</dt><dd>${money(T.got)}</dd><div class="are-rentroll-meter" style="--are-rentroll-got:${pct.toFixed(1)}%"><i></i></div><small>${pct.toFixed(1)}% of ${money(T.billed)} billed</small></dl>
    <dl class="are-rentroll-kpi"><dt>Arrears</dt><dd class="${T.arrears ? 'is-bad' : ''}">${money(T.arrears)}</dd><small>${T.late.length} unit${T.late.length === 1 ? '' : 's'} owing</small></dl>
    <dl class="are-rentroll-kpi"><dt>Leases ending ≤ 90 days</dt><dd>${T.exp}</dd><small>${U.filter(u => u.kind === 'notice').length} have given notice</small></dl>
    <dl class="are-rentroll-kpi"><dt>Avg rent</dt><dd>$${T.ppsf.toFixed(2)}<small style="font-size:12px"> /ft²</small></dd><small>${money(res.filter(occupied).reduce((s, u) => s + u.rent, 0) / T.occ)} a month per home</small></dl>`;
  const lg = $('[data-legend]');
  if (S.lens === 'rent') lg.innerHTML = `<span class="are-rentroll-ramp" style="--a:color-mix(in oklch, var(--are-rentroll-accent) 20%, var(--are-rentroll-vacant));--b:var(--are-rentroll-accent)">$${PMIN.toFixed(2)}<i></i>$${PMAX.toFixed(2)} per ft² a month</span>`;
  else {
    const items = S.lens === 'status' ? Object.entries(ST).map(([k, v]) => [k, v[0], color(v[1]), U.filter(u => status(u) === k).length])
      : [...EXP.map(e => [e[0], e[1], color(e[2]), U.filter(u => (occupied(u) || u.kind === 'shop') && e[3](u)).length]), ['vac', 'Vacant', 'var(--are-rentroll-faint)', U.filter(u => !occupied(u) && u.kind !== 'shop').length]];
    lg.innerHTML = items.map(([k, l, c, n]) => `<button type="button" data-act="hide" data-v="${k}" style="--c:${c}" aria-pressed="${!S.hide.has(k)}" title="${S.hide.has(k) ? 'Show' : 'Fade'} ${l.toLowerCase()} units">${l} <small>${n}</small></button>`).join('') +
      (S.hide.size ? '<button type="button" class="are-rentroll-clear" data-act="showall">Show all</button>' : '');
  }
}

/* ── the stacking plan ────────────────────────────────────────────────── */
const grid = $('[data-grid]'), cells = new Map();
function buildGrid() {
  let h = '';
  for (let f = 8; f >= 1; f--) {
    h += `<div class="are-rentroll-row" role="row"><span class="are-rentroll-fl" role="rowheader">${f}</span>`;
    U.filter(u => u.f === f).forEach((u, i) => { h += `<div class="are-rentroll-gc" role="gridcell"><button type="button" class="are-rentroll-u" data-act="unit" data-id="${u.id}" tabindex="-1" style="--i:${(8 - f) * 6 + i}"><span class="are-rentroll-n"><span>${u.id}</span><em></em></span><span class="are-rentroll-v"></span><span class="are-rentroll-bar"></span></button></div>`; });
    h += '</div>';
  }
  h += `<div class="are-rentroll-row" role="row"><span class="are-rentroll-fl" role="rowheader">G</span>${U.filter(u => u.kind === 'shop').map(u => `<div class="are-rentroll-gc is-shop" role="gridcell"><button type="button" class="are-rentroll-u is-shop" data-act="unit" data-id="${u.id}" tabindex="-1"><span class="are-rentroll-n"><span>${u.id} · ${esc(u.tenant)}</span><em></em></span><span class="are-rentroll-v"></span><span class="are-rentroll-bar"></span></button></div>`).join('')}</div>`;
  grid.innerHTML = h;
  $$('[data-id]', grid).forEach(el => cells.set(el.dataset.id, el));
}
function renderGrid() {
  U.forEach(u => {
    const el = cells.get(u.id), L = look(u), st = status(u);
    el.style.setProperty('--c', L.c);
    $('em', el).textContent = L.tag;
    $('.are-rentroll-v', el).textContent = L.v;
    $('.are-rentroll-bar', el).style.setProperty('--p', occupied(u) || u.kind === 'shop' ? Math.min(100, u.end / 15 * 100).toFixed(0) + '%' : '0%');
    el.classList.toggle('is-dim', S.lens !== 'rent' && S.hide.has(L.key));
    el.classList.toggle('is-sel', S.sel === u.id);
    el.parentElement.setAttribute('aria-selected', S.sel === u.id);
    el.setAttribute('aria-pressed', S.sel === u.id);
    el.tabIndex = S.focus === u.id ? 0 : -1;
    el.setAttribute('aria-label', `${u.kind === 'shop' ? 'Shop ' + u.id + ', ' + u.tenant : 'Unit ' + u.id + ', ' + u.type}, ${ST[st][0]}${balance(u) > 0 ? ', owes ' + money(balance(u)) : ''}, ${money(u.rent)} a month`);
  });
}

/* ── unit panel ───────────────────────────────────────────────────────── */
const panel = $('[data-panel]');
function renderPanel(focus) {
  const u = byId[S.sel];
  if (!u) {
    const T = totals(), late = T.late;
    panel.innerHTML = `<div class="are-rentroll-pbody"><div class="are-rentroll-hint">${I.bldg}<b>Pick a unit on the plan</b><span>Its lease, ledger and actions open here. Arrow keys move around the building.</span></div>
      ${late.length ? `<section><h4>Owing in ${MS[S.month]} · ${money(T.arrears)}</h4><ul class="are-rentroll-log">${late.map(x => `<li><span>${x.id}</span>${esc(x.tenant)} · ${money(balance(x))}</li>`).join('')}</ul></section>
        <div class="are-rentroll-acts"><button type="button" class="are-rentroll-btn are-rentroll-primary" data-act="remindall" ${S.month < 2 ? 'disabled title="Reminders go out for the current month"' : ''}>Remind all ${late.length}</button></div>` : '<p class="are-rentroll-note">Nobody owes rent this month.</p>'}</div>`;
    return;
  }
  const st = status(u), L = color(ST[st][1]), bal = balance(u), led = u.ledger.filter(e => e.m <= S.month);
  let run = 0;
  const rows = led.map(e => { run += e.amt; return `<tr class="${e.fresh ? 'is-new' : ''}"><td>${MS[e.m]} ${e.d}</td><td>${esc(e.what)}</td><td class="${e.amt < 0 ? 'is-pay' : ''}">${money(e.amt)}</td><td>${money(run)}</td></tr>`; }).join('');
  led.forEach(e => { e.fresh = false; });
  const F = S.f;
  let acts = '', extra = '';
  if (occupied(u) || u.kind === 'shop') {
    acts = `<button type="button" class="are-rentroll-btn are-rentroll-primary" data-act="payform" ${bal <= 0 ? 'disabled title="Nothing owed"' : S.month < 2 ? 'disabled title="Payments are recorded in the current month"' : ''}>Record payment</button>
      <button type="button" class="are-rentroll-btn" data-act="remind" ${bal <= 0 ? 'disabled title="Nothing owed"' : S.month < 2 ? 'disabled title="Reminders go out for the current month"' : ''}>Send reminder</button>
      ${u.kind === 'notice' ? `<button type="button" class="are-rentroll-btn" data-act="inspect">Book move-out inspection</button>` : u.kind === 'occ' ? `<button type="button" class="are-rentroll-btn" data-act="renewform">Offer renewal</button>` : ''}`;
    if (S.form === 'pay') extra = `<form class="are-rentroll-form" data-payform novalidate><label>Amount<span class="are-rentroll-in"><span>$</span><input name="amt" inputmode="decimal" value="${esc(F.amt || bal)}" ${F.err ? 'aria-invalid="true"' : ''} aria-describedby="are-rentroll-pe"></span></label><small id="are-rentroll-pe">${F.err}</small>
        <div class="are-rentroll-chips" role="radiogroup" aria-label="Method">${['ACH', 'Check', 'Card'].map(m => `<button type="button" role="radio" data-act="method" data-v="${m}" aria-checked="${F.method === m}">${m}</button>`).join('')}</div>
        <div class="are-rentroll-row2"><button type="submit" class="are-rentroll-btn are-rentroll-primary">Record ${money(+String(F.amt || bal).replace(/[^0-9.]/g, '') || 0)}</button><button type="button" class="are-rentroll-btn" data-act="formclose">Cancel</button></div></form>`;
    if (S.form === 'renew') { const nr = Math.round(u.rent * (1 + F.pct / 100) / 5) * 5; extra = `<form class="are-rentroll-form" data-renewform novalidate><label>Increase</label><div class="are-rentroll-row2" style="align-items:center"><button type="button" class="are-rentroll-btn" data-act="pct" data-v="-0.5" ${F.pct <= 0 ? 'disabled title="No decrease below current rent"' : ''} aria-label="Lower the increase">−</button><b style="font:700 15px var(--are-rentroll-mono);min-width:56px;text-align:center">${F.pct.toFixed(1)}%</b><button type="button" class="are-rentroll-btn" data-act="pct" data-v="0.5" ${F.pct >= 8 ? 'disabled title="Capped at 8% by the lease"' : ''} aria-label="Raise the increase">+</button><span class="are-rentroll-note">${money(u.rent)} → <b style="color:var(--are-rentroll-ink)">${money(nr)}</b> from ${endLabel(u)}</span></div>
        <div class="are-rentroll-row2"><button type="submit" class="are-rentroll-btn are-rentroll-primary">Send 12-month offer</button><button type="button" class="are-rentroll-btn" data-act="formclose">Cancel</button></div></form>`; }
  } else if (u.kind === 'vacant') {
    acts = `<button type="button" class="are-rentroll-btn" data-act="listed" aria-pressed="${u.listed}">${u.listed ? 'Listed online' : 'Not listed'}</button><button type="button" class="are-rentroll-btn" data-act="showing">Schedule showing</button><button type="button" class="are-rentroll-btn are-rentroll-primary" data-act="leaseform">Mark as let</button>`;
    if (S.form === 'lease') extra = `<form class="are-rentroll-form" data-leaseform novalidate><label>New tenant<span class="are-rentroll-in"><input name="name" autocomplete="off" value="${esc(F.name)}" ${F.err ? 'aria-invalid="true"' : ''} aria-describedby="are-rentroll-le"></span></label><small id="are-rentroll-le">${F.err}</small>
      <div class="are-rentroll-chips" role="radiogroup" aria-label="Move-in">${['Nov 1', 'Nov 15'].map(m => `<button type="button" role="radio" data-act="start" data-v="${m}" aria-checked="${F.start === m}">${m}</button>`).join('')}</div>
      <div class="are-rentroll-row2"><button type="submit" class="are-rentroll-btn are-rentroll-primary">Sign 12-month lease at ${money(u.rent)}</button><button type="button" class="are-rentroll-btn" data-act="formclose">Cancel</button></div></form>`;
  } else if (u.kind === 'turn') {
    extra = `<section><h4>Make-ready · ${Object.values(u.checks).filter(Boolean).length} of 4</h4><div class="are-rentroll-checks">${Object.entries(u.checks).map(([k, v]) => `<button type="button" role="checkbox" data-act="check" data-v="${esc(k)}" aria-checked="${v}"><i>${I.check}</i>${k}<small>${v ? 'done' : 'to do'}</small></button>`).join('')}</div></section>`;
  }
  panel.innerHTML = `<header class="are-rentroll-ph" style="--c:${L}"><button type="button" class="are-rentroll-iconb are-rentroll-back" data-act="back" aria-label="Back to the building">${I.back}</button><span class="are-rentroll-big">${u.id}</span>
      <div class="are-rentroll-who"><b>${u.tenant ? esc(u.tenant) : 'Vacant'}</b><span>${u.type} · ${u.sf.toLocaleString('en-US')} ft²${u.f ? ' · floor ' + u.f : ' · street level'}</span></div>
      <span class="are-rentroll-chip" style="--c:${L}">${ST[st][0]}</span><button type="button" class="are-rentroll-iconb" data-act="close" aria-label="Close unit" title="Close (Esc)">${I.x}</button></header>
    <div class="are-rentroll-pbody">
      <dl class="are-rentroll-facts"><div><dt>${occupied(u) || u.kind === 'shop' ? 'Rent' : 'Asking rent'}</dt><dd>${money(u.rent)}/mo</dd></div><div><dt>Per ft²</dt><dd>$${(u.rent / u.sf).toFixed(2)}</dd></div>
        ${occupied(u) || u.kind === 'shop' ? `<div><dt>Lease ends</dt><dd>${u.kind === 'notice' ? 'Moving out ' + u.moveOut : endLabel(u)}</dd></div><div><dt>Deposit held</dt><dd>${money(u.rent)}</dd></div>` : `<div><dt>Empty for</dt><dd>${u.vacantDays} days</dd></div><div><dt>Last tenant</dt><dd>${esc(u.prev)}</dd></div>`}</dl>
      ${led.length ? `<section><h4>Ledger to ${MS[S.month]}</h4><table class="are-rentroll-ledger"><thead><tr><th>Date</th><th>Item</th><th>Amount</th><th>Balance</th></tr></thead><tbody>${rows}</tbody><tfoot><tr><td></td><td>${bal > 0 ? 'Owed' : 'Balance'}</td><td></td><td class="${bal > 0 ? 'is-owed' : ''}">${money(bal)}</td></tr></tfoot></table></section>` : `<p class="are-rentroll-note">No charges since ${esc(u.prev || 'the last tenant')} moved out.</p>`}
      <div class="are-rentroll-acts">${acts}</div>
      ${extra}
      <section><h4>Activity</h4><ul class="are-rentroll-log">${u.log.map(l => `<li><span>${esc(l[0])}</span>${esc(l[1])}</li>`).join('') || '<li><span>—</span>Nothing logged yet</li>'}</ul></section>
    </div>`;
  const pf = $('[data-payform]', panel), rf = $('[data-renewform]', panel), lf = $('[data-leaseform]', panel);
  if (pf) { pf.addEventListener('submit', e => { e.preventDefault(); pay(u, pf.amt.value); }); pf.amt.addEventListener('input', () => { S.f.amt = pf.amt.value; const b = $('[type="submit"]', pf); b.textContent = 'Record ' + money(+pf.amt.value.replace(/[^0-9.]/g, '') || 0); }); }
  if (rf) rf.addEventListener('submit', e => { e.preventDefault(); renew(u); });
  if (lf) { lf.addEventListener('submit', e => { e.preventDefault(); lease(u, lf.name.value); }); lf.name.addEventListener('input', () => { S.f.name = lf.name.value; }); }
  if (focus) { const n = $(focus, panel); if (n) n.focus({ preventScroll: true }); }
}

/* ── actions ──────────────────────────────────────────────────────────── */
function pay(u, raw) {
  const amt = Math.round(parseFloat(String(raw).replace(/[^0-9.]/g, '')) * 100) / 100, bal = balance(u);
  if (!(amt > 0)) { S.f.err = 'Enter the amount received'; renderPanel('[name="amt"]'); return; }
  if (amt > bal) { S.f.err = `That is more than the ${money(bal)} owed`; renderPanel('[name="amt"]'); return; }
  u.ledger.push({ m: 2, d: 2, what: (amt < bal ? 'Partial payment · ' : 'Payment · ') + S.f.method, amt: -amt, fresh: true });
  u.log.unshift(['Oct 2', `${S.f.method} payment of ${money(amt)} recorded`]);
  S.form = null; S.f.err = ''; S.f.amt = '';
  render(); renderPanel('[data-act="close"]');
  toast(`${u.id}: ${money(amt)} recorded · ${balance(u) > 0 ? money(balance(u)) + ' still owed' : 'paid up'}`);
}
function renew(u) {
  const nr = Math.round(u.rent * (1 + S.f.pct / 100) / 5) * 5;
  u.log.unshift(['Oct 2', `Renewal offered at ${money(nr)} (${S.f.pct.toFixed(1)}%)`]);
  S.form = null; renderPanel('[data-act="close"]');
  toast(`Renewal sent to ${u.tenant}: ${money(nr)} a month from ${endLabel(u)}`);
}
function lease(u, name) {
  if (!name.trim()) { S.f.err = 'Who is moving in?'; renderPanel('[name="name"]'); return; }
  Object.assign(u, { kind: 'occ', tenant: name.trim(), end: 13, listed: false });
  u.log.unshift(['Oct 2', `Let to ${name.trim()} from ${S.f.start}`]);
  S.form = null; S.f = { method: 'ACH', amt: '', err: '', pct: 3, name: '', start: 'Nov 1' };
  render(); renderPanel('[data-act="close"]');
  toast(`${u.id} let to ${name.trim()} · occupancy ${(totals().occ / totals().n * 100).toFixed(1)}%`);
}
/* ── render ───────────────────────────────────────────────────────────── */
function render() { renderTop(); renderGrid(); root.dataset.pane = S.pane; }
function toast(msg) {
  const box = $('[data-toasts]'), t = doc.createElement('div');
  t.className = 'are-rentroll-toast'; t.innerHTML = `<span>${esc(msg)}</span>`;
  box.append(t);
  while (box.children.length > 2) box.firstElementChild.remove();
  setTimeout(() => { t.classList.add('is-gone'); setTimeout(() => t.remove(), 300); }, 3800);
}
function narrow() { return getComputedStyle($('.are-rentroll-ph .are-rentroll-back') || panel).display !== 'none' && !!$('.are-rentroll-ph .are-rentroll-back'); }

root.addEventListener('click', e => {
  const t = e.target.closest('[data-act]');
  if (!t || t.disabled) return;
  const v = t.dataset.v, u = byId[S.sel];
  switch (t.dataset.act) {
    case 'lens': S.lens = v; S.hide.clear(); render(); break;
    case 'month': S.month = clamp(S.month + +v, 0, 2); S.form = null; render(); renderPanel(); break;
    case 'hide': S.hide.has(v) ? S.hide.delete(v) : S.hide.add(v); render(); break;
    case 'showall': S.hide.clear(); render(); break;
    case 'unit': {
      const id = t.dataset.id;
      S.sel = id; S.focus = id; S.form = null; S.f.err = ''; S.f.amt = '';
      render(); renderPanel();
      if (narrow()) { S.pane = 'unit'; render(); renderPanel('[data-act="back"]'); }
      break;
    }
    case 'close': { const id = S.sel; S.sel = null; S.pane = 'stack'; S.form = null; render(); renderPanel(); const c = cells.get(id); if (c) c.focus({ preventScroll: true }); break; }
    case 'back': S.pane = 'stack'; render(); { const c = cells.get(S.sel); if (c) c.focus({ preventScroll: true }); } break;
    case 'payform': S.form = 'pay'; S.f.err = ''; S.f.amt = String(balance(u)); renderPanel('[name="amt"]'); break;
    case 'renewform': S.form = 'renew'; renderPanel('[data-act="pct"]'); break;
    case 'leaseform': S.form = 'lease'; S.f.err = ''; renderPanel('[name="name"]'); break;
    case 'formclose': S.form = null; S.f.err = ''; renderPanel('[data-act="close"]'); break;
    case 'method': S.f.method = v; { const a = $('[name="amt"]', panel); if (a) S.f.amt = a.value; } renderPanel(`[data-act="method"][data-v="${v}"]`); break;
    case 'pct': S.f.pct = clamp(S.f.pct + +v, 0, 8); renderPanel(`[data-act="pct"][data-v="${v}"]`); break;
    case 'start': S.f.start = v; { const n = $('[name="name"]', panel); if (n) S.f.name = n.value; } renderPanel(`[data-act="start"][data-v="${v}"]`); break;
    case 'remind': u.log.unshift(['Oct 2', `Reminder sent for ${money(balance(u))}`]); renderPanel('[data-act="remind"]'); toast(`Reminder sent to ${u.tenant} for ${money(balance(u))}`); break;
    case 'remindall': { const late = totals().late; late.forEach(x => x.log.unshift(['Oct 2', `Reminder sent for ${money(balance(x))}`])); t.disabled = true; t.textContent = `Sent to ${late.length}`; t.title = 'Reminders already sent today'; toast(`Reminders sent to ${late.length} households · ${money(totals().arrears)} outstanding`); break; }
    case 'inspect': u.log.unshift(['Oct 2', `Move-out inspection booked for ${u.moveOut}, 10:00`]); renderPanel('[data-act="inspect"]'); toast(`Inspection booked for ${u.id} on ${u.moveOut}`); break;
    case 'listed': u.listed = !u.listed; u.log.unshift(['Oct 2', u.listed ? 'Listed on Hearthline at ' + money(u.rent) : 'Listing paused']); render(); renderPanel('[data-act="listed"]'); break;
    case 'showing': u.log.unshift(['Oct 2', 'Showing booked Sat 11:30']); renderPanel('[data-act="showing"]'); toast(`Showing booked at ${u.id} for Sat 11:30`); break;
    case 'check': u.checks[v] = !u.checks[v];
      if (Object.values(u.checks).every(Boolean)) { u.kind = 'vacant'; u.listed = false; u.log.unshift(['Oct 2', 'Make-ready finished']); render(); renderPanel('[data-act="listed"]'); toast(`${u.id} is ready to let`); }
      else { render(); renderPanel(`[data-act="check"][data-v="${v}"]`); }
      break;
  }
});

/* ── keyboard: a roving grid ──────────────────────────────────────────── */
function cellAt(id, dx, dy) {
  const u = byId[id];
  if (u.kind === 'shop') {
    if (dy < 0) return String(100 + u.c + 1 + (dx > 0 ? 2 : 0));
    if (dx) { const o = U.filter(x => x.kind === 'shop'); const i = o.indexOf(u); return (o[i + dx] || u).id; }
    return null;
  }
  if (dy > 0 && u.f === 1) return u.c < 3 ? 'R1' : 'R2';
  const f = clamp(u.f - dy, 1, 8), c = clamp(u.c + dx, 0, 5);
  return String(f * 100 + c + 1);
}
root.addEventListener('keydown', e => {
  const t = e.target;
  if (e.key === 'Escape') {
    if (S.form) { S.form = null; renderPanel('[data-act="close"]'); e.preventDefault(); return; }
    if (S.sel) { e.preventDefault(); $('[data-act="close"]', panel) && $('[data-act="close"]', panel).click(); }
    return;
  }
  if (t.matches('input') || e.metaKey || e.ctrlKey || e.altKey) return;
  if (t.matches('.are-rentroll-u')) {
    const dir = { ArrowRight: [1, 0], ArrowLeft: [-1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[e.key];
    if (dir) { e.preventDefault(); const n = cellAt(t.dataset.id, dir[0], dir[1]); if (n && cells.get(n)) { S.focus = n; renderGrid(); cells.get(n).focus(); } return; }
    if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); const u = byId[t.dataset.id]; const n = u.kind === 'shop' ? (e.key === 'Home' ? 'R1' : 'R2') : String(u.f * 100 + (e.key === 'Home' ? 1 : 6)); S.focus = n; renderGrid(); cells.get(n).focus(); return; }
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); t.click(); return; }
  }
  const g = t.closest('[role="radiogroup"]');
  if (g && /^Arrow(Left|Right)$/.test(e.key)) { e.preventDefault(); const items = $$('[role="radio"]', g), i = items.indexOf(t), n = items[(i + (e.key === 'ArrowRight' ? 1 : -1) + items.length) % items.length]; n.click(); const a = $(`[data-act="${n.dataset.act}"][data-v="${n.dataset.v}"]`); if (a) a.focus(); return; }
  if (e.key === 'l' || e.key === 'L') { S.lens = LENSES[(LENSES.findIndex(l => l[0] === S.lens) + 1) % 3][0]; S.hide.clear(); render(); }
});

/* ── boot ─────────────────────────────────────────────────────────────── */
buildGrid();
render();
renderPanel();

css:
.are-hoods {
  /* theme: override these four to re-skin */
  --are-hoods-bg: oklch(0.984 0.005 100);
  --are-hoods-ink: oklch(0.23 0.03 262);
  --are-hoods-accent: oklch(0.56 0.19 352);
  --are-hoods-card: oklch(1 0 0);

  --are-hoods-line: color-mix(in oklch, var(--are-hoods-ink) 10%, transparent);
  --are-hoods-line2: color-mix(in oklch, var(--are-hoods-ink) 20%, transparent);
  --are-hoods-mute: color-mix(in oklch, var(--are-hoods-ink) 58%, var(--are-hoods-bg));
  --are-hoods-faint: color-mix(in oklch, var(--are-hoods-ink) 34%, var(--are-hoods-bg));
  --are-hoods-wash: color-mix(in oklch, var(--are-hoods-ink) 4%, var(--are-hoods-bg));
  --are-hoods-tint: color-mix(in oklch, var(--are-hoods-accent) 9%, var(--are-hoods-bg));
  --are-hoods-on: oklch(0.99 0.004 100);
  --are-hoods-f0: oklch(0.63 0.16 32);
  --are-hoods-f1: oklch(0.55 0.14 255);
  --are-hoods-f2: oklch(0.55 0.14 290);
  --are-hoods-f3: oklch(0.57 0.12 72);
  --are-hoods-f4: oklch(0.6 0.13 148);
  --are-hoods-f5: oklch(0.62 0.09 205);
  --are-hoods-f6: oklch(0.57 0.17 352);
  --are-hoods-mono: ui-monospace, "SF Mono", Menlo, monospace;
  --are-hoods-ease: cubic-bezier(.2, .8, .2, 1);
  --are-hoods-spring: linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1);

  position: relative; width: 100%; height: var(--are-hoods-h, 680px);
  container-type: inline-size; container-name: are-hoods;
  overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--are-hoods-bg); color: var(--are-hoods-ink); color-scheme: light;
  accent-color: var(--are-hoods-accent);
  font: 13px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  border-radius: 14px; box-shadow: 0 0 0 1px var(--are-hoods-line);
  -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--are-hoods-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & h3, & h4, & p, & ol, & ul { margin: 0; }
  & ol, & ul { padding: 0; list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 10px/1 var(--are-hoods-mono); padding: 2px 4px; min-width: 16px; text-align: center; border: 1px solid var(--are-hoods-line2); border-bottom-width: 2px; border-radius: 4px; color: var(--are-hoods-mute); background: var(--are-hoods-card); }
}

.are-hoods .are-hoods-app {
  position: relative; height: 100%; display: grid;
  grid-template-columns: clamp(232px, 23cqi, 270px) minmax(0, 1fr) clamp(300px, 33cqi, 390px);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "top top top" "panes panes panes" "prio rank cmp";
}

/* ── header ───────────────────────────────────────── */
.are-hoods .are-hoods-top { grid-area: top; display: flex; align-items: center; gap: 16px; padding: 10px 16px; border-bottom: 1px solid var(--are-hoods-line); }
.are-hoods .are-hoods-brand {
  display: flex; align-items: center; gap: 10px; min-width: 0;
  & svg { width: 24px; height: 24px; color: var(--are-hoods-accent); }
  & div { display: grid; line-height: 1.2; }
  & b { font-weight: 780; font-size: 15px; letter-spacing: -.02em; }
  & span { font-size: 11.5px; color: var(--are-hoods-mute); white-space: nowrap; }
}
.are-hoods .are-hoods-presets {
  display: flex; gap: 4px; margin-left: auto;
  & button, & .is-custom { display: inline-flex; align-items: center; gap: 6px; height: 30px; padding: 0 10px; border-radius: 15px; border: 0; background: var(--are-hoods-wash); box-shadow: inset 0 0 0 1px var(--are-hoods-line); font-weight: 600; font-size: 12px; white-space: nowrap; transition: background .2s, color .2s, box-shadow .2s; }
  & button:hover { box-shadow: inset 0 0 0 1px var(--are-hoods-line2); }
  & button[aria-checked="true"] { background: var(--are-hoods-ink); color: var(--are-hoods-on); box-shadow: none; }
  & button[aria-checked="true"] kbd { background: transparent; color: inherit; border-color: color-mix(in oklch, var(--are-hoods-on) 35%, transparent); }
  & .is-custom { background: none; box-shadow: inset 0 0 0 1px var(--are-hoods-line); color: var(--are-hoods-mute); font-style: italic; cursor: default; }
}
.are-hoods .are-hoods-budget {
  display: grid; grid-template-columns: auto 140px auto; align-items: center; gap: 8px;
  & label { font-size: 12px; font-weight: 600; color: var(--are-hoods-mute); }
  & input { width: 100%; margin: 0; }
  & output { font: 700 13px/1 var(--are-hoods-mono); font-variant-numeric: tabular-nums; min-width: 58px; }
}
.are-hoods .are-hoods-panes { grid-area: panes; display: none; }
.are-hoods .are-hoods-sechead { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; & h3 { font-size: 14px; font-weight: 750; letter-spacing: -.01em; text-wrap: balance; } }
.are-hoods .are-hoods-sub { font-size: 11.5px; color: var(--are-hoods-mute); text-align: right; text-wrap: pretty; }
.are-hoods .are-hoods-link { border: 0; background: none; padding: 0; font-size: 12px; font-weight: 600; color: var(--are-hoods-accent); text-decoration: underline; text-underline-offset: 3px; }

/* ── priorities ───────────────────────────────────── */
.are-hoods .are-hoods-prio { grid-area: prio; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 14px 16px; border-right: 1px solid var(--are-hoods-line); display: flex; flex-direction: column; gap: 16px; & > * { flex: none; } }
.are-hoods .are-hoods-sliders { display: grid; gap: 12px; }
.are-hoods .are-hoods-sl {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 3px 8px; align-items: center;
  & label { display: flex; align-items: center; gap: 7px; font-size: 12.5px; font-weight: 600; }
  & label i { width: 9px; height: 9px; border-radius: 3px; background: var(--c); flex: none; }
  & output { font: 650 11px/1 var(--are-hoods-mono); color: var(--are-hoods-mute); font-variant-numeric: tabular-nums; }
  & input { grid-column: 1 / -1; width: 100%; margin: 0; accent-color: var(--c); height: 16px; }
  & .are-hoods-pips { grid-column: 1 / -1; display: flex; justify-content: space-between; padding: 0 6px; margin-top: -4px; }
  & .are-hoods-pips span { width: 3px; height: 3px; border-radius: 50%; background: var(--are-hoods-line2); }
  &:has(input[value="0"]) label { color: var(--are-hoods-faint); }
}
.are-hoods .are-hoods-work { display: grid; gap: 6px; & .are-hoods-lbl { font-size: 12px; font-weight: 600; color: var(--are-hoods-mute); } }
.are-hoods .are-hoods-seg {
  display: flex; padding: 3px; gap: 2px; border-radius: 9px; background: var(--are-hoods-wash); box-shadow: inset 0 0 0 1px var(--are-hoods-line);
  & button { flex: 1 1 0; height: 28px; border: 0; border-radius: 6px; background: none; font-weight: 600; font-size: 12px; color: var(--are-hoods-mute); transition: background .2s, color .2s, box-shadow .2s; }
  & button[aria-checked="true"] { background: var(--are-hoods-card); color: var(--are-hoods-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--are-hoods-ink) 15%, transparent), 0 0 0 1px var(--are-hoods-line); }
}

/* ── ranking ──────────────────────────────────────── */
.are-hoods .are-hoods-rank { grid-area: rank; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 14px 16px; }
.are-hoods .are-hoods-list { display: grid; gap: 8px; }
.are-hoods .are-hoods-item {
  position: relative; display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; grid-template-areas: "n main score" "n bar bar"; gap: 6px 12px; padding: 12px 14px 12px 12px; border-radius: 14px;
  background: var(--are-hoods-card); box-shadow: 0 0 0 1px var(--are-hoods-line), 0 1px 2px color-mix(in oklch, var(--are-hoods-ink) 6%, transparent);
  transition: box-shadow .25s, opacity .3s;
  &:has([aria-pressed="true"]) { box-shadow: 0 0 0 1.5px var(--slot), 0 6px 18px -12px var(--slot); }
  &.is-over { opacity: .72; }
  & .are-hoods-n { grid-area: n; align-self: start; font: 800 22px/1 var(--are-hoods-mono); letter-spacing: -.05em; color: var(--are-hoods-faint); padding-top: 2px; }
  &:first-child .are-hoods-n { color: var(--are-hoods-accent); }
  & .are-hoods-main { grid-area: main; min-width: 0; display: grid; gap: 2px; }
  & h4 { display: flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 720; letter-spacing: -.01em; }
  & h4 small { font: 700 9.5px/1 var(--are-hoods-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--are-hoods-f0); padding: 3px 5px; border-radius: 4px; background: color-mix(in oklch, var(--are-hoods-f0) 12%, transparent); }
  & p { font-size: 12px; color: var(--are-hoods-mute); text-wrap: pretty; }
  & .are-hoods-facts { display: flex; flex-wrap: wrap; gap: 2px 12px; font: 500 11.5px/1.4 var(--are-hoods-mono); color: var(--are-hoods-mute); font-variant-numeric: tabular-nums; }
  & .are-hoods-facts b { color: var(--are-hoods-ink); font-weight: 650; }
  & .are-hoods-score { grid-area: score; display: grid; justify-items: end; gap: 6px; }
  & .are-hoods-score b { font: 800 26px/1 var(--are-hoods-mono); letter-spacing: -.05em; font-variant-numeric: tabular-nums; }
  & .are-hoods-score b small { font-size: 11px; color: var(--are-hoods-mute); letter-spacing: 0; }
  & .are-hoods-bar { grid-area: bar; display: flex; height: 8px; border-radius: 4px; background: var(--are-hoods-wash); overflow: hidden; gap: 1px; }
  & .are-hoods-bar i { display: block; flex: none; height: 100%; width: calc(var(--w) * 1%); background: var(--c); transition: width .6s var(--are-hoods-ease); }
}
.are-hoods .are-hoods-pick {
  display: inline-flex; align-items: center; gap: 6px; height: 26px; padding: 0 9px 0 7px; border-radius: 13px; border: 0; background: var(--are-hoods-wash); box-shadow: inset 0 0 0 1px var(--are-hoods-line2); font-size: 11.5px; font-weight: 650; white-space: nowrap;
  & i { width: 14px; height: 14px; border-radius: 4px; box-shadow: inset 0 0 0 1.5px var(--are-hoods-line2); display: grid; place-items: center; }
  & i svg { width: 10px; height: 10px; stroke-width: 3; color: var(--are-hoods-on); opacity: 0; }
  &[aria-pressed="true"] { background: color-mix(in oklch, var(--slot) 12%, var(--are-hoods-card)); box-shadow: inset 0 0 0 1px var(--slot); color: color-mix(in oklch, var(--slot) 70%, var(--are-hoods-ink)); }
  &[aria-pressed="true"] i { background: var(--slot); box-shadow: none; }
  &[aria-pressed="true"] i svg { opacity: 1; }
}

/* ── compare ──────────────────────────────────────── */
.are-hoods .are-hoods-cmp { grid-area: cmp; min-height: 0; display: flex; flex-direction: column; padding: 14px 16px 12px; border-left: 1px solid var(--are-hoods-line); background: color-mix(in oklch, var(--are-hoods-bg) 60%, var(--are-hoods-wash)); }
.are-hoods .are-hoods-radar {
  flex: none; position: relative; height: clamp(210px, 34cqb, 250px);
  & svg { width: 100%; height: 100%; display: block; overflow: visible; stroke: none; }
  & .are-hoods-ring { fill: none; stroke: var(--are-hoods-line); }
  & .are-hoods-spoke { stroke: var(--are-hoods-line); }
  & .are-hoods-axl { font: 650 10px system-ui; fill: var(--are-hoods-mute); text-anchor: middle; cursor: default; transition: fill .2s; }
  & .are-hoods-axl.is-hot { fill: var(--are-hoods-ink); }
  & .are-hoods-shape { fill: color-mix(in oklch, var(--c) 14%, transparent); stroke: var(--c); stroke-width: 2; stroke-linejoin: round; transition: opacity .3s; }
  & .are-hoods-shape.is-dim { opacity: .2; }
  & .are-hoods-vtx { fill: var(--are-hoods-card); stroke: var(--c); stroke-width: 1.5; }
}
.are-hoods .are-hoods-tablewrap { flex: 1 1 auto; min-height: 0; overflow: auto; scrollbar-width: thin; margin-top: 8px; }
.are-hoods .are-hoods-table {
  width: 100%; border-collapse: collapse; font-size: 11.5px; font-variant-numeric: tabular-nums; table-layout: fixed;
  & th { text-align: right; font-weight: 700; padding: 6px 4px; position: sticky; top: 0; background: color-mix(in oklch, var(--are-hoods-bg) 60%, var(--are-hoods-wash)); line-height: 1.2; vertical-align: bottom; }
  & th:first-child { width: 30%; }
  & th span { display: inline-flex; align-items: center; gap: 5px; }
  & th span::before { content: ""; width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & th:first-child, & td:first-child { text-align: left; }
  & td { padding: 6px 4px; border-top: 1px solid var(--are-hoods-line); text-align: right; font-family: var(--are-hoods-mono); white-space: nowrap; transition: background .2s; overflow: hidden; text-overflow: ellipsis; }
  & td:first-child { font-family: system-ui; color: var(--are-hoods-mute); white-space: normal; line-height: 1.25; }
  & td.is-best { font-weight: 750; color: var(--are-hoods-ink); }
  & td.is-best::after { content: ""; display: inline-block; width: 5px; height: 5px; margin-left: 5px; border-radius: 50%; background: var(--are-hoods-accent); vertical-align: middle; }
  & tr.is-hot td { background: var(--are-hoods-tint); }
}
.are-hoods .are-hoods-empty { padding: 24px 8px; text-align: center; color: var(--are-hoods-mute); text-wrap: balance; }

.are-hoods .are-hoods-toasts { position: absolute; left: 50%; bottom: 16px; translate: -50% 0; z-index: 40; display: grid; gap: 8px; justify-items: center; pointer-events: none; width: max-content; max-width: calc(100% - 32px); }
.are-hoods .are-hoods-toast {
  pointer-events: auto; display: flex; align-items: center; gap: 10px; padding: 9px 14px; border-radius: 11px; background: var(--are-hoods-ink); color: var(--are-hoods-on); font-size: 12.5px;
  box-shadow: 0 16px 34px -12px color-mix(in oklch, var(--are-hoods-ink) 70%, transparent); transition: opacity .25s, translate .45s var(--are-hoods-spring);
  @starting-style { opacity: 0; translate: 0 12px; }
  &.is-gone { opacity: 0; translate: 0 8px; }
}

/* ── responsive ──────────────────────────────────── */
@container are-hoods (max-width: 1100px) {
  .are-hoods .are-hoods-brand span { display: none; }
  .are-hoods .are-hoods-presets kbd { display: none; }
  .are-hoods .are-hoods-item p { display: none; }
}
@container are-hoods (max-width: 959px) {
  .are-hoods .are-hoods-app { grid-template-columns: clamp(220px, 28cqi, 250px) minmax(0, 1fr); grid-template-areas: "top top" "panes panes" "prio rank"; }
  .are-hoods .are-hoods-top { flex-wrap: wrap; gap: 8px 12px; }
  .are-hoods .are-hoods-presets { margin-left: 0; order: 3; flex: 1 1 100%; overflow-x: auto; scrollbar-width: none; }
  .are-hoods .are-hoods-budget { margin-left: auto; }
  .are-hoods .are-hoods-panes { display: flex; gap: 2px; padding: 6px 12px; border-bottom: 1px solid var(--are-hoods-line);
    & button { flex: 1 1 0; height: 30px; border: 0; border-radius: 7px; background: none; font-weight: 650; color: var(--are-hoods-mute); }
    & button[aria-selected="true"] { background: var(--are-hoods-ink); color: var(--are-hoods-on); }
    & button[data-v="prio"] { display: none; }
  }
  .are-hoods .are-hoods-rank, .are-hoods .are-hoods-cmp { grid-area: rank; border-left: 0; }
  .are-hoods[data-pane="cmp"] .are-hoods-rank { display: none; }
  .are-hoods:not([data-pane="cmp"]) .are-hoods-cmp { display: none; }
}
@container are-hoods (max-width: 759px) {
  .are-hoods .are-hoods-app { grid-template-columns: minmax(0, 1fr); grid-template-areas: "top" "panes" "body"; }
  .are-hoods .are-hoods-panes button[data-v="prio"] { display: block; }
  .are-hoods .are-hoods-prio, .are-hoods .are-hoods-rank, .are-hoods .are-hoods-cmp { grid-area: body; border: 0; }
  .are-hoods:not([data-pane="prio"]) .are-hoods-prio { display: none; }
  .are-hoods[data-pane="prio"] .are-hoods-rank { display: none; }
  .are-hoods[data-pane="cmp"] .are-hoods-rank { display: none; }
  .are-hoods .are-hoods-budget { grid-template-columns: auto minmax(0, 1fr) auto; flex: 1 1 100%; order: 4; }
}
@container are-hoods (max-width: 440px) {
  .are-hoods .are-hoods-item { grid-template-columns: 24px minmax(0, 1fr) auto; gap: 6px 8px; padding: 10px; }
  .are-hoods .are-hoods-item .are-hoods-score b { font-size: 21px; }
  .are-hoods .are-hoods-item .are-hoods-facts span:nth-child(n + 3) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .are-hoods *, .are-hoods *::before, .are-hoods *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

