/* ── Groundwork · neighbourhood match ───────────────────────────────────
   Raw facts per neighbourhood are normalised to 0–100 per factor. A match
   is the weighted mean of those scores, and each factor's share
   (weight × score ÷ total weight) is drawn as a segment of the bar, so the
   segments always add up to the number beside them. Ranking changes FLIP;
   preset changes tween the weights so the sliders glide into place. */
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const SPRING = 'linear(0, 0.09 4%, 0.33 9%, 0.66 15%, 0.9 21%, 1.03 27%, 1.07 32%, 1.05 38%, 1.01 47%, 0.995 58%, 1)';
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const UID = Math.random().toString(36).slice(2, 7);
$$('[id]').forEach(el => { const o = el.id, n = o + '-' + UID; el.id = n; $$(`[for="${o}"]`).forEach(x => x.setAttribute('for', n)); $$(`[aria-labelledby="${o}"]`).forEach(x => x.setAttribute('aria-labelledby', n)); });
const CHECK = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>';

/* ── facts ────────────────────────────────────────────────────────────── */
const H = [
  { id: 'mill', n: 'Millbrook', t: 'Edwardian terraces around Alder Common', price: 760000, com: [18, 26], school: 8.4, walk: 78, green: 22, db: 54, yld: 3.9, trend: 24 },
  { id: 'fen', n: 'Fenwick Hill', t: 'Big gardens and the best primary in the city', price: 1180000, com: [24, 31], school: 9.3, walk: 55, green: 34, db: 46, yld: 3.1, trend: 31 },
  { id: 'tan', n: 'Old Tannery', t: 'Warehouse lofts, bakeries and late trams', price: 590000, com: [12, 20], school: 6.8, walk: 92, green: 9, db: 63, yld: 5.2, trend: 38 },
  { id: 'quay', n: 'Quayside', t: 'Waterfront towers next to the ferry', price: 720000, com: [9, 8], school: 7.1, walk: 88, green: 12, db: 61, yld: 4.6, trend: 19 },
  { id: 'ash', n: 'Ashgrove', t: 'Quiet crescents ten minutes from the park', price: 690000, com: [21, 14], school: 8.0, walk: 70, green: 26, db: 52, yld: 4.3, trend: 27 },
  { id: 'salt', n: 'Saltmarsh', t: 'Bungalows by the reserve, room to grow', price: 510000, com: [28, 17], school: 7.2, walk: 58, green: 31, db: 48, yld: 5.6, trend: 16 },
];
const F = [
  { k: 'price', n: 'Price fit', s: (h, S) => clamp((1.25 - h.price / S.budget) / 0.75 * 100, 0, 100), raw: h => kfmt(h.price), best: 'min', val: h => h.price },
  { k: 'com', n: 'Short commute', s: (h, S) => clamp((40 - h.com[S.work]) / 32 * 100, 0, 100), raw: (h, S) => h.com[S.work] + ' min', best: 'min', val: (h, S) => h.com[S.work] },
  { k: 'school', n: 'Schools', s: h => clamp((h.school - 5) / 5 * 100, 0, 100), raw: h => h.school.toFixed(1) + '/10', best: 'max', val: h => h.school },
  { k: 'walk', n: 'Walkable', s: h => h.walk, raw: h => h.walk + '/100', best: 'max', val: h => h.walk },
  { k: 'green', n: 'Green space', s: h => clamp(h.green / 35 * 100, 0, 100), raw: h => h.green + '%', best: 'max', val: h => h.green },
  { k: 'quiet', n: 'Quiet streets', s: h => clamp((70 - h.db) / 25 * 100, 0, 100), raw: h => h.db + ' dB', best: 'min', val: h => h.db },
  { k: 'yld', n: 'Rental yield', s: h => clamp((h.yld - 2.5) / 3.5 * 100, 0, 100), raw: h => h.yld.toFixed(1) + '%', best: 'max', val: h => h.yld },
];
const PRESETS = [
  ['family', 'Family', [3, 2, 5, 2, 4, 4, 0]], ['commute', 'Commuter', [3, 5, 1, 4, 1, 1, 0]],
  ['invest', 'Investor', [4, 1, 1, 2, 0, 0, 5]], ['quiet', 'Quiet life', [2, 0, 1, 2, 5, 5, 0]],
];
const SLOTS = ['oklch(0.52 0.15 255)', 'oklch(0.63 0.17 32)', 'oklch(0.58 0.13 155)'];
const kfmt = n => n >= 1e6 ? '$' + (n / 1e6).toFixed(2) + 'M' : '$' + Math.round(n / 1000) + 'k';
const S = { w: PRESETS[0][2].slice(), budget: 850000, work: 0, picks: [], pane: 'rank', hot: null, axis: null };

/* ── maths ────────────────────────────────────────────────────────────── */
function rank() {
  const tw = S.w.reduce((a, b) => a + b, 0) || 1;
  return H.map(h => {
    const sc = F.map(f => f.s(h, S)), parts = sc.map((v, i) => S.w[i] * v / tw);
    return { h, sc, parts, score: parts.reduce((a, b) => a + b, 0) };
  }).sort((a, b) => b.score - a.score || a.h.price - b.h.price);
}
const preset = () => PRESETS.find(p => p[2].every((v, i) => v === Math.round(S.w[i])));

/* ── header & sliders ─────────────────────────────────────────────────── */
function renderHead() {
  const p = preset();
  $('[data-presets]').innerHTML = PRESETS.map(([k, l], i) => `<button type="button" role="radio" data-act="preset" data-v="${k}" aria-checked="${p && p[0] === k}" tabindex="${(p ? p[0] === k : i === 0) ? 0 : -1}">${l}<kbd>${i + 1}</kbd></button>`).join('') + (p ? '' : '<span class="is-custom">Custom</span>');
  const b = $('[data-budget]');
  if (doc.activeElement !== b) b.value = S.budget;
  b.setAttribute('aria-valuetext', '$' + S.budget.toLocaleString('en-US'));
  $('[data-budgetout]').textContent = '$' + (S.budget >= 1e6 ? (S.budget / 1e6).toFixed(2) + 'M' : Math.round(S.budget / 1000) + 'k');
  $('[data-work]').innerHTML = [['Downtown', 0], ['Harbour Park', 1]].map(([l, v]) => `<button type="button" role="radio" data-act="work" data-v="${v}" aria-checked="${S.work === v}" tabindex="${S.work === v ? 0 : -1}">${l}</button>`).join('');
  $$('[data-act="pane"]').forEach(x => x.setAttribute('aria-selected', x.dataset.v === S.pane));
  root.dataset.pane = S.pane;
}
function buildSliders() {
  $('[data-sliders]').innerHTML = F.map((f, i) => `<div class="are-hoods-sl" style="--c:var(--are-hoods-f${i})"><label for="are-hoods-w${i}-${UID}"><i></i>${f.n}</label><output data-wout="${i}"></output>
    <input id="are-hoods-w${i}-${UID}" type="range" min="0" max="5" step="1" data-w="${i}"><span class="are-hoods-pips" aria-hidden="true">${'<span></span>'.repeat(6)}</span></div>`).join('');
}
const WORDS = ['ignore', 'a little', 'some', 'matters', 'a lot', 'essential'];
function renderSliders() {
  $$('[data-w]').forEach(inp => {
    const i = +inp.dataset.w, v = Math.round(S.w[i]);
    if (doc.activeElement !== inp) inp.value = S.w[i];
    inp.setAttribute('value', v);
    inp.setAttribute('aria-valuetext', WORDS[v]);
    $(`[data-wout="${i}"]`).textContent = WORDS[v];
  });
}

/* ── ranking list with FLIP ───────────────────────────────────────────── */
const list = $('[data-list]'), items = new Map();
function renderList(animate) {
  const R = rank(), before = new Map();
  if (animate && !RM.matches) items.forEach((el, k) => before.set(k, el.getBoundingClientRect().top));
  const full = S.picks.length >= 3;
  R.forEach((r, i) => {
    const h = r.h;
    let li = items.get(h.id);
    if (!li) {
      li = doc.createElement('li'); li.className = 'are-hoods-item'; li.dataset.id = h.id;
      li.innerHTML = `<span class="are-hoods-n"></span><div class="are-hoods-main"><h4>${h.n}<small hidden>Over budget</small></h4><p>${esc(h.t)}</p><div class="are-hoods-facts"></div></div>
        <div class="are-hoods-score"><b></b><button type="button" class="are-hoods-pick" data-act="pick" data-v="${h.id}"><i>${CHECK}</i><span>Compare</span></button></div><div class="are-hoods-bar" role="img"></div>`;
      items.set(h.id, li);
    }
    const slot = S.picks.indexOf(h.id), on = slot > -1;
    li.style.setProperty('--slot', on ? SLOTS[slot] : 'var(--are-hoods-line2)');
    $('.are-hoods-n', li).textContent = i + 1;
    $('.are-hoods-score b', li).innerHTML = `${Math.round(r.score)}<small>/100</small>`;
    const over = h.price > S.budget;
    $('h4 small', li).hidden = !over; li.classList.toggle('is-over', over);
    $('.are-hoods-facts', li).innerHTML = `<span><b>${kfmt(h.price)}</b> median</span><span><b>${h.com[S.work]} min</b> to ${S.work ? 'Harbour Park' : 'downtown'}</span><span><b>${h.school.toFixed(1)}</b> schools</span><span><b>${h.trend > 0 ? '+' : ''}${h.trend}%</b> 5 yr</span>`;
    const bar = $('.are-hoods-bar', li);
    bar.innerHTML = r.parts.map((p, k) => p > 0.05 ? `<i style="--w:${p.toFixed(2)};--c:var(--are-hoods-f${k})" title="${F[k].n}: ${p.toFixed(1)} pts"></i>` : '').join('');
    bar.setAttribute('aria-label', `${h.n} scores ${Math.round(r.score)}: ` + r.parts.map((p, k) => p > 0.05 ? `${F[k].n} ${p.toFixed(1)}` : '').filter(Boolean).join(', '));
    const pk = $('.are-hoods-pick', li);
    pk.setAttribute('aria-pressed', on);
    pk.setAttribute('aria-label', on ? `Remove ${h.n} from the comparison` : `Compare ${h.n}`);
    const lock = !on && full;
    pk.disabled = lock; pk.title = lock ? 'Compare up to three; remove one first' : '';
    if (list.children[i] !== li) list.insertBefore(li, list.children[i] || null);
  });
  if (animate && !RM.matches) items.forEach((el, k) => {
    const a = before.get(k); if (a == null) return;
    const dy = a - el.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) { el.getAnimations().forEach(x => x.cancel()); el.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 560, easing: SPRING }); }
  });
  const p = preset();
  $('[data-ranktitle]').textContent = p ? `Best for “${p[1]}”` : 'Best for your priorities';
  $('[data-ranksub]').textContent = `${H.filter(h => h.price <= S.budget).length} of 6 within $${Math.round(S.budget / 1000)}k`;
  return R;
}

/* ── radar + table ────────────────────────────────────────────────────── */
const radar = $('[data-radar]'), RAD = 96;
const ang = i => -Math.PI / 2 + i * 2 * Math.PI / F.length;
const pt = (i, v) => [Math.cos(ang(i)) * RAD * v / 100, Math.sin(ang(i)) * RAD * v / 100];
let shapesNow = {}, radarRaf = 0;
function buildRadar() {
  let g = '';
  [25, 50, 75, 100].forEach(r => { g += `<polygon class="are-hoods-ring" points="${F.map((_, i) => pt(i, r).map(n => n.toFixed(1)).join(',')).join(' ')}"/>`; });
  F.forEach((f, i) => {
    const [x, y] = pt(i, 100), [lx, ly] = pt(i, 122);
    g += `<line class="are-hoods-spoke" x1="0" y1="0" x2="${x.toFixed(1)}" y2="${y.toFixed(1)}"/><text class="are-hoods-axl" data-axis="${i}" x="${lx.toFixed(1)}" y="${(ly + 3.5).toFixed(1)}">${f.n}</text>`;
  });
  g += '<g data-shapes></g>';
  radar.innerHTML = g;
}
function renderCompare(R) {
  const picked = S.picks.map(id => R.find(r => r.h.id === id));
  const target = Object.fromEntries(picked.map(r => [r.h.id, r.sc.slice()]));
  const box = $('[data-shapes]', radar);
  /* tween every vertex from where it is now to where it should be */
  const from = {};
  picked.forEach(r => { from[r.h.id] = shapesNow[r.h.id] || r.sc.map(() => 0); });
  box.innerHTML = picked.map((r, k) => `<g data-shape="${r.h.id}" style="--c:${SLOTS[k]}"><polygon class="are-hoods-shape"/>${F.map(() => '<circle class="are-hoods-vtx" r="2.6"/>').join('')}</g>`).join('');
  const draw = t => {
    picked.forEach(r => {
      const g = $(`[data-shape="${r.h.id}"]`, box), vals = from[r.h.id].map((v, i) => v + (target[r.h.id][i] - v) * t);
      shapesNow[r.h.id] = vals;
      const P = vals.map((v, i) => pt(i, Math.max(v, 3)));
      $('polygon', g).setAttribute('points', P.map(p => p.map(n => n.toFixed(1)).join(',')).join(' '));
      $$('circle', g).forEach((c, i) => { c.setAttribute('cx', P[i][0].toFixed(1)); c.setAttribute('cy', P[i][1].toFixed(1)); });
    });
  };
  cancelAnimationFrame(radarRaf);
  if (RM.matches) draw(1);
  else {
    const t0 = performance.now();
    const step = now => {
      if (!root.isConnected) return;
      const k = Math.min(1, (now - t0) / 520), e = 1 - Math.pow(1 - k, 3);
      draw(e);
      if (k < 1) radarRaf = requestAnimationFrame(step);
    };
    draw(0); radarRaf = requestAnimationFrame(step);
  }
  Object.keys(shapesNow).forEach(k => { if (!target[k]) delete shapesNow[k]; });
  radar.setAttribute('aria-label', picked.length ? 'Radar of ' + picked.map(r => r.h.n + ' ' + Math.round(r.score)).join(', ') : 'Nothing selected to compare');
  $('[data-cmpsub]').textContent = picked.length ? `${picked.length} of 3 · tap Compare on a card` : 'Pick up to three to compare';
  const t = $('[data-table]');
  if (!picked.length) { t.innerHTML = '<tbody><tr><td class="are-hoods-empty">Choose neighbourhoods with Compare to see them side by side.</td></tr></tbody>'; return; }
  t.innerHTML = `<thead><tr><th></th>${picked.map((r, k) => `<th style="--c:${SLOTS[k]}"><span>${r.h.n}</span></th>`).join('')}</tr></thead><tbody>
    <tr><td>Match</td>${(() => { const best = Math.max(...picked.map(r => r.score)); return picked.map(r => `<td class="${picked.length > 1 && r.score === best ? 'is-best' : ''}">${Math.round(r.score)}</td>`).join(''); })()}</tr>
    ${F.map((f, i) => { const vals = picked.map(r => f.val(r.h, S)), b = f.best === 'min' ? Math.min(...vals) : Math.max(...vals); return `<tr data-row="${i}" class="${S.axis === i ? 'is-hot' : ''}"><td>${f.n}</td>${picked.map((r, k) => `<td class="${picked.length > 1 && vals[k] === b ? 'is-best' : ''}">${f.raw(r.h, S)}</td>`).join('')}</tr>`; }).join('')}
    <tr><td>5-year change</td>${picked.map(r => `<td>${r.h.trend > 0 ? '+' : ''}${r.h.trend}%</td>`).join('')}</tr></tbody>`;
}

/* ── render ───────────────────────────────────────────────────────────── */
function render(animate = true) { renderHead(); renderSliders(); const R = renderList(animate); renderCompare(R); }
function toast(msg) {
  const box = $('[data-toasts]'), t = doc.createElement('div');
  t.className = 'are-hoods-toast'; t.textContent = msg;
  box.append(t);
  while (box.children.length > 2) box.firstElementChild.remove();
  setTimeout(() => { t.classList.add('is-gone'); setTimeout(() => t.remove(), 300); }, 3400);
}
let tween = 0;
function applyPreset(k) {
  const p = PRESETS.find(x => x[0] === k), from = S.w.slice(), before = rank()[0].h.n;
  cancelAnimationFrame(tween);
  const finish = () => { S.w = p[2].slice(); render(true); const top = rank()[0].h.n; toast(top === before ? `${p[1]}: ${top} still leads` : `${p[1]}: ${top} moves to the top`); };
  if (RM.matches) { finish(); return; }
  const t0 = performance.now();
  renderHead();
  const step = now => {
    if (!root.isConnected) return;
    const e = 1 - Math.pow(1 - Math.min(1, (now - t0) / 380), 3);
    S.w = from.map((v, i) => v + (p[2][i] - v) * e);
    renderSliders();
    if (e < 1) tween = requestAnimationFrame(step); else finish();
  };
  tween = requestAnimationFrame(step);
}

/* ── events ───────────────────────────────────────────────────────────── */
root.addEventListener('click', e => {
  const t = e.target.closest('[data-act]');
  if (!t || t.disabled) return;
  const v = t.dataset.v;
  switch (t.dataset.act) {
    case 'preset': applyPreset(v); { const b = $(`[data-act="preset"][data-v="${v}"]`); if (b) b.focus({ preventScroll: true }); } break;
    case 'reset': applyPreset('family'); S.budget = 850000; S.work = 0; break;
    case 'work': S.work = +v; render(true); $(`[data-act="work"][data-v="${v}"]`).focus({ preventScroll: true }); break;
    case 'pick': {
      const i = S.picks.indexOf(v);
      if (i > -1) S.picks.splice(i, 1); else if (S.picks.length < 3) S.picks.push(v);
      render(false);
      const b = $(`[data-act="pick"][data-v="${v}"]`); if (b) b.focus({ preventScroll: true });
      break;
    }
    case 'pane': S.pane = v; renderHead(); break;
  }
});
root.addEventListener('input', e => {
  const t = e.target;
  if (t.matches('[data-w]')) { cancelAnimationFrame(tween); S.w = S.w.map(Math.round); S.w[+t.dataset.w] = +t.value; render(true); }
  if (t.matches('[data-budget]')) { S.budget = +t.value; render(true); }
});
radar.addEventListener('pointerover', e => { const a = e.target.closest('[data-axis]'); hotAxis(a ? +a.dataset.axis : null); });
radar.addEventListener('pointerleave', () => hotAxis(null));
function hotAxis(i) {
  if (S.axis === i) return;
  S.axis = i;
  $$('[data-axis]', radar).forEach(a => a.classList.toggle('is-hot', +a.dataset.axis === i));
  $$('[data-row]').forEach(r => r.classList.toggle('is-hot', +r.dataset.row === i));
}
root.addEventListener('keydown', e => {
  const t = e.target;
  if (t.matches('input') || e.metaKey || e.ctrlKey || e.altKey) return;
  const g = t.closest('[role="radiogroup"]');
  if (g && /^Arrow(Left|Right)$/.test(e.key)) { e.preventDefault(); const it = $$('[role="radio"]', g), i = it.indexOf(t), n = it[(i + (e.key === 'ArrowRight' ? 1 : -1) + it.length) % it.length]; n.click(); return; }
  if (/^[1-4]$/.test(e.key)) applyPreset(PRESETS[+e.key - 1][0]);
});

/* ── boot ─────────────────────────────────────────────────────────────── */
buildSliders();
buildRadar();
S.picks = rank().slice(0, 3).map(r => r.h.id);
render(false);
